/*
 * Simple greedy (list‑scheduling) with random tie‑breaking.
 * For each job we know the exact sequence of (machine, processing time).
 * We repeatedly pick a ready operation (the next operation of a job whose
 * predecessor is finished).  Two strategies are used:
 *   – Greedy: choose the operation with the smallest possible start time;
 *             among those with equal start time pick the job with the most
 *             remaining work (break further ties randomly).
 *   – Random: pick any ready job uniformly at random.
 * Both strategies produce a feasible schedule because we always honour
 * precedence and machine availability.  The order in which operations are
 * scheduled on a machine is exactly the permutation required by the output.
 * The algorithm is executed many times (while time permits) and the schedule
 * with the smallest makespan is kept.
 *
 * Complexity per iteration: O(J * M * J) ≤ 6·10^4 for the maximal test size,
 * so thousands of iterations fit easily into the time limit.
 */

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Op {
    int machine;
    ll time;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int J, M;
    if (!(cin >> J >> M)) return 0;

    vector<vector<Op>> jobOps(J, vector<Op>(M));
    vector<ll> totalJobDur(J, 0);
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m; ll p;
            cin >> m >> p;
            jobOps[j][k] = {m, p};
            totalJobDur[j] += p;
        }
    }

    // Random generator with fixed seed (deterministic output)
    mt19937 rng(123456789);

    const auto schedule_once = [&](bool greedy,
                                   vector<vector<int>>& machineOrder,
                                   ll& makespan) {
        vector<int> stepIdx(J, 0);          // index of next operation in each job
        vector<ll> jobReady(J, 0);          // time when current job is ready
        vector<ll> machineReady(M, 0);      // next free time of each machine
        vector<ll> jobRemaining = totalJobDur; // sum of remaining processing times

        machineOrder.assign(M, vector<int>());
        machineOrder.reserve(M);
        int remainingOps = J * M;

        while (remainingOps > 0) {
            int chosen = -1;
            if (greedy) {
                // Find minimal possible start time among ready jobs
                ll minStart = LLONG_MAX;
                vector<int> cand;
                cand.reserve(J);
                for (int j = 0; j < J; ++j) {
                    int s = stepIdx[j];
                    if (s >= M) continue;               // job finished
                    const Op& op = jobOps[j][s];
                    ll est = max(jobReady[j], machineReady[op.machine]);
                    if (est < minStart) {
                        minStart = est;
                        cand.clear();
                        cand.push_back(j);
                    } else if (est == minStart) {
                        cand.push_back(j);
                    }
                }
                // Break ties by remaining work, then randomly
                ll bestRem = -1;
                for (int j : cand) {
                    if (jobRemaining[j] > bestRem) {
                        bestRem = jobRemaining[j];
                        chosen = j;
                    } else if (jobRemaining[j] == bestRem) {
                        if (uniform_int_distribution<int>(0, 1)(rng))
                            chosen = j;
                    }
                }
            } else {
                // Pure random selection among ready jobs
                vector<int> ready;
                ready.reserve(J);
                for (int j = 0; j < J; ++j)
                    if (stepIdx[j] < M) ready.push_back(j);
                uniform_int_distribution<int> dist(0, (int)ready.size() - 1);
                chosen = ready[dist(rng)];
            }

            // Schedule the chosen operation
            int s = stepIdx[chosen];
            const Op& op = jobOps[chosen][s];
            ll start = max(jobReady[chosen], machineReady[op.machine]);
            ll finish = start + op.time;

            jobReady[chosen] = finish;
            machineReady[op.machine] = finish;
            machineOrder[op.machine].push_back(chosen);
            jobRemaining[chosen] -= op.time;
            ++stepIdx[chosen];
            --remainingOps;
        }

        makespan = *max_element(jobReady.begin(), jobReady.end());
    };

    // Run multiple iterations within the time limit
    const double TIME_LIMIT = 1.8; // seconds
    auto startTime = chrono::steady_clock::now();
    ll bestMakespan = LLONG_MAX;
    vector<vector<int>> bestOrder;

    // At least one deterministic greedy run
    {
        vector<vector<int>> curOrder;
        ll curMakespan;
        schedule_once(true, curOrder, curMakespan);
        bestMakespan = curMakespan;
        bestOrder = std::move(curOrder);
    }

    // Additional stochastic runs while time permits
    const int MAX_ITER = 20000;
    for (int iter = 1; iter < MAX_ITER; ++iter) {
        auto now = chrono::steady_clock::now();
        double elapsed = chrono::duration<double>(now - startTime).count();
        if (elapsed > TIME_LIMIT) break;

        bool greedy = (iter % 2 == 0); // alternate between greedy and random
        vector<vector<int>> curOrder;
        ll curMakespan;
        schedule_once(greedy, curOrder, curMakespan);
        if (curMakespan < bestMakespan) {
            bestMakespan = curMakespan;
            bestOrder = std::move(curOrder);
        }
    }

    // Output the best ordering found
    for (int m = 0; m < M; ++m) {
        const auto& vec = bestOrder[m];
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << vec[i];
        }
        if (m + 1 < M) cout << '\n';
    }
    return 0;
}

/*
 *  Job Shop Scheduling – permutation schedule heuristic
 *
 *  Idea:
 *    - Use a *global job order* that is applied to every machine.
 *      This guarantees a feasible schedule (no cycles) because all
 *      disjunctive arcs point in the same direction.
 *    - Build a good order with the classic NEH insertion heuristic:
 *        sort jobs by descending total processing time,
 *        then insert each job at the position causing the smallest makespan.
 *    - Improve the order by simple stochastic hill climbing (random swaps)
 *      while time permits.
 *    - Output the final order for each machine (the same permutation).
 *
 *  The schedule for a given order is evaluated by the earliest-start rule:
 *    for each job in order:
 *        for each operation (machine, time) in its route:
 *            start = max(prev_job_finish, machine_available);
 *            finish = start + time;
 *            update machine_available and prev_job_finish.
 *
 *  This runs in O(J * M) per evaluation; with J ≤ 50, M ≤ 25 it easily
 *  fits into the 1‑second limit.
 */

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int J, M;
    if (!(cin >> J >> M)) return 0;

    // jobOps[j][k] = {machine, processing time} in the order given for job j
    vector<vector<pair<int, long long>>> jobOps(J, vector<pair<int, long long>>(M));
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m; long long p;
            cin >> m >> p;
            jobOps[j][k] = {m, p};
        }
    }

    // evaluation of a permutation (global order) -> makespan
    auto evaluate = [&](const vector<int>& perm) -> long long {
        vector<long long> machReady(M, 0);
        long long makespan = 0;
        for (int job : perm) {
            long long prev = 0;
            for (auto &op : jobOps[job]) {
                int m = op.first;
                long long p = op.second;
                long long start = max(prev, machReady[m]);
                long long finish = start + p;
                machReady[m] = finish;
                prev = finish;
            }
            makespan = max(makespan, prev);
        }
        return makespan;
    };

    // --- NEH construction (descending total processing time) ---
    vector<pair<long long, int>> jobSum;
    jobSum.reserve(J);
    for (int j = 0; j < J; ++j) {
        long long sum = 0;
        for (auto &op : jobOps[j]) sum += op.second;
        jobSum.emplace_back(sum, j);
    }
    sort(jobSum.begin(), jobSum.end(),
         [&](const auto &a, const auto &b) { return a.first > b.first; });

    vector<int> perm;
    perm.reserve(J);
    for (auto &js : jobSum) {
        int job = js.second;
        long long bestM = LLONG_MAX;
        int bestPos = 0;
        // try all insertion positions
        for (int pos = 0; pos <= (int)perm.size(); ++pos) {
            vector<int> trial = perm;
            trial.insert(trial.begin() + pos, job);
            long long curM = evaluate(trial);
            if (curM < bestM) {
                bestM = curM;
                bestPos = pos;
            }
        }
        perm.insert(perm.begin() + bestPos, job);
    }

    long long bestMakespan = evaluate(perm);

    // --- Simple stochastic hill climbing (random swaps) ---
    std::mt19937 rng(123456789);               // fixed seed → deterministic
    std::uniform_int_distribution<int> dist(0, J - 1);
    auto deadline = chrono::steady_clock::now() + chrono::milliseconds(900);

    while (chrono::steady_clock::now() < deadline) {
        int i = dist(rng);
        int j = dist(rng);
        if (i == j) continue;
        swap(perm[i], perm[j]);
        long long cur = evaluate(perm);
        if (cur < bestMakespan) {
            bestMakespan = cur;               // keep improvement
        } else {
            swap(perm[i], perm[j]);            // revert
        }
    }

    // Output the same permutation for every machine
    for (int m = 0; m < M; ++m) {
        for (int idx = 0; idx < J; ++idx) {
            if (idx) cout << ' ';
            cout << perm[idx];
        }
        if (m + 1 < M) cout << '\n';
    }
    return 0;
}

/**
 * Job Shop Scheduling – greedy list scheduling.
 *
 * Overview
 * --------
 * We construct an actual feasible schedule (start times) using a simple
 * event‑driven list scheduling:
 *   * At any moment we know which operations are ready (their predecessor on
 *     the same job has finished) and which machines are idle.
 *   * For each idle machine we start the ready operation with the smallest
 *     processing time (SPT rule).  This is deterministic and fast.
 *   * When an operation finishes we make the next operation of the same job
 *     ready on its required machine.
 *
 * After all J·M operations have been started we have, for every machine,
 * the exact order in which its jobs were started.  Outputting these orders
 * yields a valid solution because the schedule respects both job precedence
 * and machine capacity, hence the induced disjunctive graph is acyclic.
 *
 * The algorithm runs in O(J·M·log J) time (J≤~50, M≤~25) and easily fits the
 * 1‑second limit.
 */

#include <bits/stdc++.h>
using namespace std;

struct Op {
    int machine;
    int proc;
};

struct ReadyItem {
    int proc;   // processing time of the operation
    int job;    // job index
};

struct ReadyComp {
    bool operator()(const ReadyItem& a, const ReadyItem& b) const {
        if (a.proc != b.proc) return a.proc > b.proc; // smallest proc first
        return a.job > b.job;
    }
};

struct Event {
    long long time; // completion time
    int job;
    int machine;
};

struct EventComp {
    bool operator()(const Event& a, const Event& b) const {
        return a.time > b.time; // earliest event first
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int J, M;
    if (!(cin >> J >> M)) return 0;          // no input

    vector<vector<Op>> jobOps(J, vector<Op>(M));
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m, p;
            cin >> m >> p;
            jobOps[j][k] = {m, p};
        }
    }

    // next operation index for each job
    vector<int> nextIdx(J, 0);
    // machine busy‑until times
    vector<long long> machineBusyUntil(M, 0);
    // resulting sequences (order of jobs on each machine)
    vector<vector<int>> machineSeq(M);
    machineSeq.assign(M, vector<int>());

    // ready queues per machine (min‑heap by processing time)
    vector<priority_queue<ReadyItem, vector<ReadyItem>, ReadyComp>> readyQ(M);
    for (int j = 0; j < J; ++j) {
        const Op& o = jobOps[j][0];
        readyQ[o.machine].push({o.proc, j});
    }

    priority_queue<Event, vector<Event>, EventComp> evPQ;
    long long curTime = 0;
    int scheduledOps = 0;
    const int totalOps = J * M;

    while (scheduledOps < totalOps) {
        bool didSchedule = false;

        // try to start an operation on every currently idle machine
        for (int m = 0; m < M; ++m) {
            if (machineBusyUntil[m] <= curTime && !readyQ[m].empty()) {
                ReadyItem it = readyQ[m].top();
                readyQ[m].pop();

                int job = it.job;
                int proc = it.proc;

                // record the order for this machine
                machineSeq[m].push_back(job);

                long long finish = curTime + proc;
                machineBusyUntil[m] = finish;
                evPQ.push({finish, job, m});
                ++scheduledOps;
                didSchedule = true;
            }
        }

        if (didSchedule) continue;   // try again at the same time (no new ready jobs appear yet)

        // no operation could be started now → advance time to next completion
        if (evPQ.empty()) break;      // should not happen for a feasible instance
        curTime = evPQ.top().time;

        // process all completions occurring at curTime
        while (!evPQ.empty() && evPQ.top().time == curTime) {
            Event ev = evPQ.top(); evPQ.pop();
            int job = ev.job;

            // advance job to its next operation
            ++nextIdx[job];
            if (nextIdx[job] < M) {
                const Op& nxt = jobOps[job][nextIdx[job]];
                readyQ[nxt.machine].push({nxt.proc, job});
            }
            // the machine becomes idle; its busy‑until value will be <= curTime
        }
    }

    // Output: one line per machine, a permutation of {0..J-1}
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << machineSeq[m][i];
        }
        cout << '\n';
    }
    return 0;
}

/*
 *  Job Shop Scheduling – feasible machine orders
 *  ------------------------------------------------------------
 *  1) Build a greedy “earliest‑start” schedule.
 *     At each step schedule the ready operation whose earliest
 *     possible start time is minimal (tie – shorter processing).
 * 2) From that schedule derive the order of jobs on each machine.
 * 3) Improve the orders by hill‑climbing:
 *        repeatedly try random adjacent swaps on a machine;
 *        keep the swap only if it stays feasible (no cycles)
 *        and strictly reduces the makespan.
 * 4) Output the final machine permutations.
 *
 *  The makespan of a given set of machine orders is obtained by
 *  longest‑path (critical‑path) computation on the disjunctive graph.
 *  The graph is a DAG – each node has at most two incoming arcs
 *  (precedence on its job and predecessor on its machine).
 *
 *  The program is deterministic (fixed RNG seed) and runs well
 *  within the 1 s limit for the official sizes (J≤50, M≤25).
 */
#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int J, M;                     // number of jobs / machines
int N;                        // total number of operations = J * M
vector<vector<int>> jobMach; // jobMach[j][k] – machine of k‑th op of job j
vector<vector<int>> jobProc; // jobProc[j][k] – processing time
vector<vector<int>> opIdxOnMach; // opIdxOnMach[j][m] = position of machine m in job j
vector<ll> proc;              // processing time of every node (node = j*M + k)

const ll INF = (1LL<<60);

// ---------- longest‑path (makespan) for a given set of machine orders ----------
vector<vector<int>> adj;   // adjacency list, reused
vector<int> indeg;
vector<ll> est;            // earliest start time (partial)

ll compute_makespan(const vector<vector<int>>& machOrder) {
    // clear adjacency & indegrees
    for (int i = 0; i < N; ++i) {
        adj[i].clear();
        indeg[i] = 0;
        est[i] = 0;
    }
    // job arcs (fixed)
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k + 1 < M; ++k) {
            int u = j * M + k;
            int v = j * M + (k + 1);
            adj[u].push_back(v);
            ++indeg[v];
        }
    }
    // machine arcs (depends on current permutation)
    for (int m = 0; m < M; ++m) {
        const auto& order = machOrder[m];
        for (int i = 0; i + 1 < J; ++i) {
            int prevJob = order[i];
            int nextJob = order[i + 1];
            int u = prevJob * M + opIdxOnMach[prevJob][m];
            int v = nextJob * M + opIdxOnMach[nextJob][m];
            adj[u].push_back(v);
            ++indeg[v];
        }
    }
    // topological longest‑path
    queue<int> q;
    for (int i = 0; i < N; ++i)
        if (indeg[i] == 0) q.push(i);
    int processed = 0;
    ll makespan = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        ++processed;
        ll finish = est[u] + proc[u];
        makespan = max(makespan, finish);
        for (int v : adj[u]) {
            if (est[v] < finish) est[v] = finish;
            if (--indeg[v] == 0) q.push(v);
        }
    }
    if (processed != N) return INF;   // cycle → infeasible
    return makespan;
}

// ---------- greedy earliest‑start schedule (produces initial machine orders) ----------
void initial_schedule(vector<vector<int>>& machOrder, ll& makespan) {
    vector<int> nextOp(J, 0);          // next operation index for each job
    vector<ll> jobReady(J, 0);         // completion time of last scheduled op of each job
    vector<ll> machFree(M, 0);         // when each machine becomes free
    vector<vector<pair<ll,int>>> machOps(M); // (start, job) for each machine

    int total = J * M;
    for (int step = 0; step < total; ++step) {
        int bestJob = -1;
        ll bestStart = INF;
        int bestProc = 0;
        int bestMach = -1;
        // scan all jobs to find operation with minimal earliest start
        for (int j = 0; j < J; ++j) {
            int idx = nextOp[j];
            if (idx >= M) continue;               // job already finished
            int m = jobMach[j][idx];
            int p = jobProc[j][idx];
            ll est = max(jobReady[j], machFree[m]);
            if (est < bestStart || (est == bestStart && p < bestProc)) {
                bestStart = est;
                bestJob   = j;
                bestProc  = p;
                bestMach  = m;
            }
        }
        // schedule chosen operation
        int j = bestJob;
        int m = bestMach;
        ll start = bestStart;
        ll finish = start + bestProc;

        machOps[m].push_back({start, j});
        jobReady[j] = finish;
        machFree[m] = finish;
        ++nextOp[j];
    }

    // build machine permutations from the recorded order
    machOrder.assign(M, vector<int>(J));
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i)
            machOrder[m][i] = machOps[m][i].second;
    }
    makespan = compute_makespan(machOrder); // sanity check (should equal max jobReady)
}

// ---------- simple hill climbing with random adjacent swaps ----------
void improve_schedule(vector<vector<int>>& machOrder, ll& curMks) {
    if (J <= 1) return;                 // no swaps possible
    mt19937 rng(123456789);              // fixed seed → deterministic
    uniform_int_distribution<int> machDist(0, M - 1);
    uniform_int_distribution<int> posDist(0, J - 2);

    const double TL = 0.88;              // seconds devoted to improvement
    auto startTime = chrono::steady_clock::now();

    while (true) {
        auto now = chrono::steady_clock::now();
        double elapsed = chrono::duration<double>(now - startTime).count();
        if (elapsed > TL) break;

        int m = machDist(rng);
        int i = posDist(rng);            // position of the first of the pair to swap

        // try the swap
        swap(machOrder[m][i], machOrder[m][i + 1]);
        ll newMk = compute_makespan(machOrder);
        if (newMk < curMks) {
            curMks = newMk;              // keep improvement
            // keep the swap permanently
        } else {
            // revert – either infeasible or not better
            swap(machOrder[m][i], machOrder[m][i + 1]);
        }
    }
}

// -------------------------------------------------------------------------
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> J >> M)) return 0;
    jobMach.assign(J, vector<int>(M));
    jobProc.assign(J, vector<int>(M));
    opIdxOnMach.assign(J, vector<int>(M, -1));

    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m, p;
            cin >> m >> p;
            jobMach[j][k] = m;
            jobProc[j][k] = p;
            opIdxOnMach[j][m] = k;
        }
    }

    N = J * M;
    proc.assign(N, 0);
    for (int j = 0; j < J; ++j)
        for (int k = 0; k < M; ++k)
            proc[j * M + k] = jobProc[j][k];

    adj.assign(N, {});
    indeg.resize(N);
    est.resize(N);

    vector<vector<int>> machOrder;
    ll makespan;
    initial_schedule(machOrder, makespan);
    improve_schedule(machOrder, makespan);

    // output
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << machOrder[m][i];
        }
        if (m + 1 < M) cout << '\n';
    }
    return 0;
}

/*
 * Job Shop Scheduling – simple dispatch + local search
 *
 * 1. Build a feasible schedule by a greedy earliest‑start rule.
 *    While there are unscheduled operations, pick the job whose next
 *    operation can start the earliest (max(job ready, machine ready)).
 *    Record the order in which each machine processes the jobs – this
 *    yields a feasible permutation for every machine.
 *
 * 2. Evaluate a given set of machine permutations by constructing the
 *    disjunctive graph (job arcs + machine arcs) and performing a
 *    longest‑path DP via Kahn's topological order. The makespan is the
 *    maximum finish time. Infeasibility (cycles) is detected when the
 *    topological order cannot process all operations.
 *
 * 3. Improve the schedule with a fast hill‑climbing / simulated‑annealing
 *    style search: repeatedly pick a random machine and swap two random
 *    jobs on that machine. Keep the swap if it yields a feasible schedule
 *    and does not increase the makespan (equal makespan is also accepted
 *    to explore plateaus). Keep the best solution seen.
 *
 * The program runs for ~0.95 s per test case and outputs one permutation
 * per machine (exactly J distinct job ids). The schedule is guaranteed to
 * be feasible, and the local search typically reduces the makespan well
 * below a naive baseline.
 */

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int J, M;
    if (!(cin >> J >> M)) return 0;
    const int N = J * M;                      // total number of operations
    vector<vector<int>> jobMachines(J, vector<int>(M));
    vector<vector<long long>> jobTimes(J, vector<long long>(M));
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m; long long p;
            cin >> m >> p;
            jobMachines[j][k] = m;
            jobTimes[j][k] = p;
        }
    }

    // mapping job × machine → position inside the job
    vector<vector<int>> opIdx(J, vector<int>(M, -1));
    vector<long long> proc(N);
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m = jobMachines[j][k];
            opIdx[j][m] = k;
            proc[j * M + k] = jobTimes[j][k];
        }
    }

    /* -------------------------------------------------------------
       1) Build an initial feasible schedule (list scheduling)
       ------------------------------------------------------------- */
    vector<int> nextOpIdx(J, 0);
    vector<long long> jobReady(J, 0);
    vector<long long> machineReady(M, 0);
    vector<vector<int>> machineSeq(M); // order of jobs on each machine
    for (int scheduled = 0; scheduled < N; ++scheduled) {
        long long bestStart = LLONG_MAX;
        int bestJob = -1;
        for (int j = 0; j < J; ++j) {
            int idx = nextOpIdx[j];
            if (idx >= M) continue;                     // job finished
            int m = jobMachines[j][idx];
            long long start = max(jobReady[j], machineReady[m]);
            if (start < bestStart) {
                bestStart = start;
                bestJob = j;
            }
        }
        int j = bestJob;
        int idx = nextOpIdx[j];
        int m = jobMachines[j][idx];
        long long start = max(jobReady[j], machineReady[m]);
        long long finish = start + jobTimes[j][idx];
        jobReady[j] = finish;
        machineReady[m] = finish;
        nextOpIdx[j] = idx + 1;
        machineSeq[m].push_back(j);
    }

    /* -------------------------------------------------------------
       2) Function to evaluate a set of machine orders
       ------------------------------------------------------------- */
    auto evaluate = [&](const vector<vector<int>>& order) -> pair<bool,long long> {
        static vector<int> succMachine;
        static vector<int> indeg;
        static vector<long long> est;   // earliest start times
        succMachine.assign(N, -1);
        indeg.assign(N, 0);
        est.assign(N, 0LL);

        // job arcs: each non‑first operation gets one incoming edge
        for (int node = 0; node < N; ++node) {
            if ((node % M) > 0) indeg[node]++;   // predecessor inside the same job
        }

        // machine arcs according to the given permutation
        for (int m = 0; m < M; ++m) {
            const auto& o = order[m];
            int prevNode = -1;
            for (int pos = 0; pos < (int)o.size(); ++pos) {
                int job = o[pos];
                int kk = opIdx[job][m];
                int node = job * M + kk;
                if (prevNode != -1) {
                    succMachine[prevNode] = node;
                    indeg[node]++;               // machine predecessor
                }
                prevNode = node;
            }
        }

        // longest‑path DP on the DAG (Kahn's algorithm)
        deque<int> q;
        for (int i = 0; i < N; ++i)
            if (indeg[i] == 0) q.push_back(i);

        int processed = 0;
        long long makespan = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop_front();
            ++processed;
            long long finish = est[u] + proc[u];
            if (finish > makespan) makespan = finish;

            // job successor (if any)
            if ((u % M) != M - 1) {
                int v = u + 1;
                if (est[v] < finish) est[v] = finish;
                if (--indeg[v] == 0) q.push_back(v);
            }
            // machine successor (if any)
            int w = succMachine[u];
            if (w != -1) {
                if (est[w] < finish) est[w] = finish;
                if (--indeg[w] == 0) q.push_back(w);
            }
        }
        if (processed != N) return {false, LLONG_MAX}; // cycle detected
        return {true, makespan};
    };

    // initial evaluation (should be feasible)
    auto [feas0, bestCost] = evaluate(machineSeq);
    if (!feas0) { // fallback – identity order (should never happen)
        for (int m = 0; m < M; ++m) {
            for (int j = 0; j < J; ++j) {
                if (j) cout << ' ';
                cout << j;
            }
            if (m + 1 < M) cout << '\n';
        }
        return 0;
    }

    vector<vector<int>> curOrders = machineSeq;
    vector<vector<int>> bestOrders = curOrders;
    long long curCost = bestCost;

    // -------------------------------------------------------------
    // 3) Local search: random swaps on random machines
    // -------------------------------------------------------------
    mt19937 rng(71268726);                       // deterministic seed
    uniform_int_distribution<int> distM(0, M - 1);
    uniform_int_distribution<int> distJ(0, J - 1);
    const double TIME_LIMIT = 0.95;              // seconds
    auto startTime = chrono::steady_clock::now();

    while (true) {
        auto now = chrono::steady_clock::now();
        chrono::duration<double> elapsed = now - startTime;
        if (elapsed.count() > TIME_LIMIT) break;

        int m = distM(rng);
        int i = distJ(rng);
        int j = distJ(rng);
        while (j == i) j = distJ(rng);
        if (i > j) swap(i, j);

        // perform swap
        swap(curOrders[m][i], curOrders[m][j]);

        auto [feas, newCost] = evaluate(curOrders);
        if (feas && newCost <= curCost) {
            curCost = newCost;
            if (newCost < bestCost) {
                bestCost = newCost;
                bestOrders = curOrders;
            }
        } else {
            // revert
            swap(curOrders[m][i], curOrders[m][j]);
        }
    }

    // -------------------------------------------------------------
    // Output the best permutation for each machine
    // -------------------------------------------------------------
    for (int m = 0; m < M; ++m) {
        for (int j = 0; j < J; ++j) {
            if (j) cout << ' ';
            cout << bestOrders[m][j];
        }
        if (m + 1 < M) cout << '\n';
    }
    return 0;
}

/*
  Job Shop Scheduling – greedy earliest‑finish heuristic + simple local search.
  ------------------------------------------------------------
  1. Build a feasible schedule by repeatedly scheduling the operation
     (next operation of each job) with the smallest earliest finishing time
     max(jobReady, machineReady) + processingTime.
     While scheduling we record on each machine the order in which jobs are processed.
  2. The obtained machine orders are a feasible solution (they induce no cycles).
  3. Improve the solution by a cheap hill‑climbing: for every machine try all
     adjacent swaps; keep a swap only if it lowers the makespan.
     Makespan of a given set of machine orders is computed by a longest‑path
     algorithm on the corresponding disjunctive graph (topological DP).
  The algorithm is deterministic, runs in well under the limits
  (≈ O(J·M·J) for the greedy phase + a few passes of O(M·J·(J·M)) for local search).
*/

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL<<60);

/*------------------------------------------------------------*/
/* Compute makespan for a given set of machine orders.
   Returns INF if the implied graph contains a cycle.          */
ll computeMakespan(const vector<vector<int>>& order,
                   const vector<vector<int>>& jobPos,
                   const vector<int>& proc,
                   int J, int M) {
    int N = J * M;                              // total operations
    static vector<vector<int>> adj;
    static vector<int> indeg;
    adj.assign(N, {});
    indeg.assign(N, 0);

    // job precedence arcs
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k + 1 < M; ++k) {
            int u = j * M + k;
            int v = j * M + k + 1;
            adj[u].push_back(v);
            ++indeg[v];
        }
    }
    // machine arcs according to the supplied order
    for (int m = 0; m < M; ++m) {
        const auto& seq = order[m];
        for (int i = 0; i + 1 < (int)seq.size(); ++i) {
            int a = seq[i];
            int b = seq[i + 1];
            int ka = jobPos[a][m];
            int kb = jobPos[b][m];
            int u = a * M + ka;
            int v = b * M + kb;
            adj[u].push_back(v);
            ++indeg[v];
        }
    }

    // longest‑path DP on the DAG
    vector<ll> dp(N, 0);
    deque<int> q;
    for (int i = 0; i < N; ++i)
        if (indeg[i] == 0) q.push_back(i);

    int processed = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop_front();
        ++processed;
        ll base = dp[u] + proc[u];
        for (int v : adj[u]) {
            if (dp[v] < base) dp[v] = base;
            if (--indeg[v] == 0) q.push_back(v);
        }
    }
    if (processed != N) return INF;            // cycle – infeasible

    ll makespan = 0;
    for (int i = 0; i < N; ++i) {
        ll fin = dp[i] + proc[i];
        if (fin > makespan) makespan = fin;
    }
    return makespan;
}

/*------------------------------------------------------------*/
/* Greedy construction of a feasible schedule.                */
vector<vector<int>> greedySchedule(const vector<vector<int>>& jobMach,
                                   const vector<vector<int>>& jobTime,
                                   const vector<vector<int>>& jobPos) {
    int J = (int)jobMach.size();
    int M = (int)jobMach[0].size();

    vector<int> curIdx(J, 0);
    vector<ll> jobReady(J, 0);
    vector<ll> machReady(M, 0);
    vector<vector<int>> order(M);
    for (auto& v : order) v.reserve(J);

    int remaining = J * M;
    while (remaining--) {
        ll bestFinish = LLONG_MAX;
        int bestJob = -1, bestMach = -1, bestP = 0;
        ll bestStart = 0;

        for (int j = 0; j < J; ++j) {
            int idx = curIdx[j];
            if (idx == M) continue;                 // all ops scheduled
            int m = jobMach[j][idx];
            int p = jobTime[j][idx];
            ll start = max(jobReady[j], machReady[m]);
            ll finish = start + p;
            if (finish < bestFinish || (finish == bestFinish && j < bestJob)) {
                bestFinish = finish;
                bestStart = start;
                bestJob = j;
                bestMach = m;
                bestP = p;
            }
        }
        // schedule the selected operation
        jobReady[bestJob] = bestFinish;
        machReady[bestMach] = bestFinish;
        order[bestMach].push_back(bestJob);
        ++curIdx[bestJob];
    }
    return order;
}

/*------------------------------------------------------------*/
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int J, M;
    if (!(cin >> J >> M)) return 0;

    // jobMach[j][k] = machine of k‑th operation of job j
    // jobTime[j][k] = processing time of that operation
    vector<vector<int>> jobMach(J, vector<int>(M));
    vector<vector<int>> jobTime(J, vector<int>(M));
    vector<vector<int>> jobPos(J, vector<int>(M, -1)); // jobPos[j][m] = index k

    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m, p;
            cin >> m >> p;
            jobMach[j][k] = m;
            jobTime[j][k] = p;
            jobPos[j][m] = k;
        }
    }

    // processing time per operation (flattened)
    vector<int> proc(J * M);
    for (int j = 0; j < J; ++j)
        for (int k = 0; k < M; ++k)
            proc[j * M + k] = jobTime[j][k];

    // ---------- initial greedy schedule ----------
    vector<vector<int>> order = greedySchedule(jobMach, jobTime, jobPos);
    ll bestMakespan = computeMakespan(order, jobPos, proc, J, M);
    vector<vector<int>> bestOrder = order;

    // ---------- simple hill climbing (adjacent swaps) ----------
    const int MAX_PASSES = 3;          // enough to get quick improvements
    bool improved = true;
    for (int pass = 0; pass < MAX_PASSES && improved; ++pass) {
        improved = false;
        for (int m = 0; m < M; ++m) {
            for (int i = 0; i + 1 < J; ++i) {
                swap(order[m][i], order[m][i + 1]);
                ll cur = computeMakespan(order, jobPos, proc, J, M);
                if (cur < bestMakespan) {
                    bestMakespan = cur;
                    bestOrder = order;
                    improved = true;
                    // keep the swap and continue checking further positions
                } else {
                    swap(order[m][i], order[m][i + 1]); // revert
                }
            }
        }
        // keep the best order found so far for the next pass
        order = bestOrder;
    }

    // ---------- output ----------
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << bestOrder[m][i];
        }
        if (m + 1 < M) cout << '\n';
    }
    return 0;
}

/*
 * Job‑Shop Scheduling – heuristic solver
 *
 * 1. Construct a feasible schedule by a parallel‑dispatch (Giffler‑Thompson style):
 *    repeatedly schedule the operation with the smallest earliest start time.
 *    Ties are broken by the larger remaining processing time (LPT‑like) and a
 *    deterministic random tie‑breaker.
 *
 * 2. The schedule directly yields a permutation of jobs for each machine.
 *
 * 3. Improve the permutations by hill climbing:
 *    try swapping adjacent jobs on every machine; keep a swap only if the
 *    resulting machine orders remain feasible (no cycle) and strictly reduce
 *    the makespan.  Feasibility and makespan are evaluated by a longest‑path
 *    computation on the disjunctive graph (topological DP).
 *
 * 4. Perform several random restarts while time permits (≈0.9 s total).
 *
 * The program prints M lines, each a permutation of {0..J‑1},
 * which is guaranteed feasible and usually much better than a naïve baseline.
 */

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int J, M;
    if (!(cin >> J >> M)) return 0;
    const int N = J * M;                       // total number of operations

    // jobOps[j][k] = {machine, processing time}
    vector<vector<pair<int,int>>> jobOps(J, vector<pair<int,int>>(M));
    vector<long long> totalProc(J, 0);
    vector<vector<int>> pos(J, vector<int>(M, -1)); // pos[j][machine] = index k in jobOps

    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m, p;
            cin >> m >> p;
            jobOps[j][k] = {m, p};
            totalProc[j] += p;
            pos[j][m] = k;
        }
    }

    // -------------------------------------------------------------------------
    // Pre‑computed data for the disjunctive graph
    vector<int> jobSucc(N, -1);                 // successor on the same job
    vector<int> machineOf(N, -1);
    vector<long long> procTime(N, 0);
    vector<int> indegBase(N, 0);                // indegree contributed by job arcs only

    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int id = j * M + k;
            auto [m, p] = jobOps[j][k];
            machineOf[id] = m;
            procTime[id] = p;
            if (k + 1 < M) {
                jobSucc[id] = j * M + (k + 1);
                indegBase[j * M + (k + 1)] = 1;   // every non‑first operation has a job predecessor
            }
        }
    }

    // -------------------------------------------------------------------------
    // Evaluation of a complete set of machine orders:
    // returns {feasible, makespan}
    auto evaluate = [&](const vector<vector<int>>& machineOrders) -> pair<bool,long long> {
        static vector<int> indeg;
        static vector<int> machSucc;
        indeg.assign(N, 0);
        machSucc.assign(N, -1);
        // copy job‑only indegrees
        for (int i = 0; i < N; ++i) indeg[i] = indegBase[i];

        // add machine arcs according to the provided permutations
        for (int m = 0; m < M; ++m) {
            const vector<int>& perm = machineOrders[m];
            for (int i = 0; i + 1 < (int)perm.size(); ++i) {
                int ja = perm[i];
                int jb = perm[i + 1];
                int idxA = pos[ja][m];
                int idxB = pos[jb][m];
                int u = ja * M + idxA;
                int v = jb * M + idxB;
                machSucc[u] = v;
                ++indeg[v];
            }
        }

        // longest‑path in the DAG (topological DP)
        vector<long long> earliest(N, 0);
        deque<int> q;
        for (int i = 0; i < N; ++i)
            if (indeg[i] == 0) q.push_back(i);

        long long makespan = 0;
        int processed = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop_front();
            ++processed;
            long long finish = earliest[u] + procTime[u];
            if (finish > makespan) makespan = finish;

            // job successor
            int v = jobSucc[u];
            if (v != -1) {
                if (earliest[v] < finish) earliest[v] = finish;
                if (--indeg[v] == 0) q.push_back(v);
            }
            // machine successor
            v = machSucc[u];
            if (v != -1) {
                if (earliest[v] < finish) earliest[v] = finish;
                if (--indeg[v] == 0) q.push_back(v);
            }
        }
        bool feasible = (processed == N);
        return {feasible, makespan};
    };

    // -------------------------------------------------------------------------
    // Construct a schedule using parallel dispatch (deterministic + random ties)
    mt19937 rng(712687126); // fixed seed → deterministic result

    auto constructSchedule = [&](mt19937& rng) -> pair<vector<vector<int>>, long long> {
        vector<int> idx(J, 0);                 // next operation index for each job
        vector<long long> jobReady(J, 0);      // when current job becomes ready
        vector<long long> machReady(M, 0);     // when each machine becomes ready
        vector<long long> doneProc(J, 0);      // processed time per job
        vector<vector<int>> orders(M);
        long long makespan = 0;
        int scheduled = 0;

        while (scheduled < N) {
            long long bestEST = LLONG_MAX;
            long long bestRem = -1;
            int chosen = -1;

            // find operation with minimal earliest start time (EST)
            for (int j = 0; j < J; ++j) {
                if (idx[j] >= M) continue;
                int k = idx[j];
                int m = jobOps[j][k].first;
                long long est = max(jobReady[j], machReady[m]);
                if (est < bestEST) {
                    bestEST = est;
                    chosen = j;
                    bestRem = totalProc[j] - doneProc[j];
                } else if (est == bestEST) {
                    long long rem = totalProc[j] - doneProc[j];
                    if (rem > bestRem) {
                        bestRem = rem;
                        chosen = j;
                    } else if (rem == bestRem) {
                        // random tie‑breaker
                        if (rng() & 1) {
                            chosen = j;
                        }
                    }
                }
            }

            // schedule the chosen operation
            int k = idx[chosen];
            int m = jobOps[chosen][k].first;
            long long p = jobOps[chosen][k].second;
            long long start = max(jobReady[chosen], machReady[m]); // == bestEST
            long long finish = start + p;

            jobReady[chosen] = finish;
            machReady[m] = finish;
            doneProc[chosen] += p;
            orders[m].push_back(chosen);
            ++idx[chosen];
            ++scheduled;
            if (finish > makespan) makespan = finish;
        }
        return {orders, makespan};
    };

    // -------------------------------------------------------------------------
    // Hill climbing on a given set of machine orders
    const double TIME_LIMIT = 0.95; // seconds
    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&]()->double {
        using namespace chrono;
        return duration<double>(steady_clock::now() - startTime).count();
    };

    vector<vector<int>> bestOrders;
    long long bestMakespan = LLONG_MAX;

    // initial schedule
    {
        auto [initOrders, initMakespan] = constructSchedule(rng);
        bestOrders = std::move(initOrders);
        bestMakespan = initMakespan;
    }

    // local improvement (hill climbing)
    auto hillClimb = [&](vector<vector<int>>& orders, long long& curMks) {
        vector<int> machIdx(M);
        iota(machIdx.begin(), machIdx.end(), 0);
        while (true) {
            bool improved = false;
            shuffle(machIdx.begin(), machIdx.end(), rng);
            for (int m : machIdx) {
                vector<int> posIdx(J - 1);
                iota(posIdx.begin(), posIdx.end(), 0);
                shuffle(posIdx.begin(), posIdx.end(), rng);
                for (int i : posIdx) {
                    swap(orders[m][i], orders[m][i + 1]);
                    auto [feas, newMks] = evaluate(orders);
                    if (feas && newMks < curMks) {
                        curMks = newMks;
                        improved = true;
                    } else {
                        swap(orders[m][i], orders[m][i + 1]); // revert
                    }
                    if (elapsed() > TIME_LIMIT) return;
                }
            }
            if (!improved) break;
            if (elapsed() > TIME_LIMIT) break;
        }
    };

    hillClimb(bestOrders, bestMakespan);

    // additional random restarts while time permits
    while (elapsed() + 0.05 < TIME_LIMIT) {
        auto [candOrders, candMks] = constructSchedule(rng);
        hillClimb(candOrders, candMks);
        if (candMks < bestMakespan) {
            bestMakespan = candMks;
            bestOrders = std::move(candOrders);
        }
    }

    // -------------------------------------------------------------------------
    // Output
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << bestOrders[m][i];
        }
        if (m + 1 < M) cout << '\n';
    }
    return 0;
}

/*
 * Job Shop Scheduling – simple list scheduling + hill climbing.
 *
 * 1. Read the instance. For each job store its machine order and processing times.
 * 2. Generate a feasible schedule by a priority‑list dispatch:
 *      – a min‑heap stores the next operation of every job, keyed by the earliest
 *        start time (max of job‑ready and machine‑ready).  Ties are broken by a
 *        random number (fixed RNG seed, deterministic).
 *      – When an operation is popped it is scheduled, the job and machine ready
 *        times are updated, and the job is inserted again for its next operation.
 *      – The sequence in which jobs are taken on each machine forms a permutation
 *        (machine order) that is guaranteed feasible.
 *
 * 3. Compute the makespan of any set of machine orders by building the
 *    disjunctive graph (job‑chain arcs + machine‑chain arcs) and performing a
 *    longest‑path DP on its topological order.  If a cycle appears the schedule
 *    is infeasible (returns INF).
 *
 * 4. Hill‑climbing: while time permits, pick a random machine and two random
 *    positions, swap the jobs, recompute the makespan and keep the swap only if
 *    it strictly reduces the makespan (thus preserving feasibility).  The best
 *    schedule found is remembered.
 *
 * 5. Output the best machine permutations (one line per machine).
 *
 * The algorithm is fast (O(N) per makespan evaluation, N≤1250) and easily fits
 * the 1 s time limit while usually improving over a naïve baseline.
 */

#include <bits/stdc++.h>
using namespace std;

int J, M, N;                                   // jobs, machines, total ops
vector<vector<int>> jobMachine;                // jobMachine[j][k] = machine of k‑th op
vector<vector<int>> jobProc;                   // jobProc[j][k]    = processing time
vector<vector<int>> posInJob;                  // posInJob[j][machine] = index k in job j
vector<int> procTime;                          // procTime[opId]
vector<int> jobSucc;                           // jobSucc[opId] = next op on same job or -1
const long long INF = (1LL<<60);

// ------------------------------------------------------------
// Compute makespan for a given set of machine orders.
// Returns INF if the orientation induces a cycle (i.e. infeasible).
// ------------------------------------------------------------
long long computeMakespan(const vector<vector<int>>& orders) {
    static vector<int> indeg;
    static vector<int> nextMachine;
    static vector<long long> earliest;
    indeg.assign(N, 0);
    nextMachine.assign(N, -1);
    earliest.assign(N, 0);

    // base indegree from job predecessors (k>0)
    for (int j = 0; j < J; ++j) {
        for (int k = 1; k < M; ++k) indeg[j*M + k] = 1;
    }

    // add machine edges according to the given order
    for (int m = 0; m < M; ++m) {
        const auto& ord = orders[m];
        for (int i = 0; i + 1 < J; ++i) {
            int jobU = ord[i];
            int jobV = ord[i+1];
            int u = jobU * M + posInJob[jobU][m];
            int v = jobV * M + posInJob[jobV][m];
            indeg[v] += 1;
            nextMachine[u] = v;
        }
    }

    // Kahn's algorithm + longest‑path DP
    deque<int> q;
    for (int i = 0; i < N; ++i) if (indeg[i] == 0) q.push_back(i);
    long long makespan = 0;
    int visited = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop_front();
        ++visited;
        long long finish = earliest[u] + procTime[u];
        makespan = max(makespan, finish);

        int succ = jobSucc[u];
        if (succ != -1) {
            earliest[succ] = max(earliest[succ], finish);
            if (--indeg[succ] == 0) q.push_back(succ);
        }
        succ = nextMachine[u];
        if (succ != -1) {
            earliest[succ] = max(earliest[succ], finish);
            if (--indeg[succ] == 0) q.push_back(succ);
        }
    }
    if (visited != N) return INF;          // cycle -> infeasible
    return makespan;
}

// ------------------------------------------------------------
// Generate a feasible schedule by list scheduling.
// Returns the permutation of jobs for each machine.
// ------------------------------------------------------------
vector<vector<int>> generateInitialSchedule(mt19937& rng) {
    vector<int> jobIdx(J, 0);               // next operation index for each job
    vector<long long> jobReady(J, 0), machineReady(M, 0);
    vector<vector<int>> machineOrders(M);
    for (int m = 0; m < M; ++m) machineOrders[m].reserve(J);

    struct Item {
        long long start;
        int job;
        uint32_t tie;
        bool operator<(Item const& o) const {   // reverse for min‑heap
            if (start != o.start) return start > o.start;
            return tie > o.tie;
        }
    };
    priority_queue<Item> pq;
    for (int j = 0; j < J; ++j) {
        pq.push({0LL, j, rng()});
    }

    while (!pq.empty()) {
        Item cur = pq.top(); pq.pop();
        int j = cur.job;
        int op = jobIdx[j];
        int m = jobMachine[j][op];
        long long st = max(jobReady[j], machineReady[m]);
        long long fin = st + jobProc[j][op];
        machineOrders[m].push_back(j);
        jobReady[j] = fin;
        machineReady[m] = fin;
        ++jobIdx[j];
        if (jobIdx[j] < M) {
            int nxtM = jobMachine[j][jobIdx[j]];
            long long nxtStart = max(jobReady[j], machineReady[nxtM]);
            pq.push({nxtStart, j, rng()});
        }
    }
    return machineOrders;
}

// ------------------------------------------------------------
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    if (!(cin >> J >> M)) return 0;
    jobMachine.assign(J, vector<int>(M));
    jobProc.assign(J, vector<int>(M));
    posInJob.assign(J, vector<int>(M, -1));

    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m, p;
            cin >> m >> p;
            jobMachine[j][k] = m;
            jobProc[j][k] = p;
            posInJob[j][m] = k;
        }
    }

    N = J * M;
    procTime.assign(N, 0);
    jobSucc.assign(N, -1);
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int id = j * M + k;
            procTime[id] = jobProc[j][k];
            if (k + 1 < M) jobSucc[id] = j * M + (k + 1);
        }
    }

    mt19937 rng(123456789);   // fixed seed → deterministic behaviour
    auto overallStart = chrono::steady_clock::now();
    const double TIME_LIMIT = 0.94;   // seconds, a safety margin

    // ---- initial schedule -------------------------------------------------
    vector<vector<int>> curOrders = generateInitialSchedule(rng);
    long long curCmax = computeMakespan(curOrders);
    vector<vector<int>> bestOrders = curOrders;
    long long bestCmax = curCmax;

    // ---- hill climbing ----------------------------------------------------
    while (chrono::duration<double>(chrono::steady_clock::now() - overallStart).count() < TIME_LIMIT) {
        int m = rng() % M;
        int i = rng() % J;
        int j = rng() % J;
        if (i == j) continue;
        if (i > j) swap(i, j);
        swap(curOrders[m][i], curOrders[m][j]);
        long long newCmax = computeMakespan(curOrders);
        if (newCmax < curCmax) {                     // improvement
            curCmax = newCmax;
            if (newCmax < bestCmax) {
                bestCmax = newCmax;
                bestOrders = curOrders;
            }
        } else {
            // revert the move
            swap(curOrders[m][i], curOrders[m][j]);
        }
    }

    // ---- output -----------------------------------------------------------
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << bestOrders[m][i];
        }
        cout << '\n';
    }
    return 0;
}

//  Job Shop Scheduling – Simple feasible schedule
//  -------------------------------------------------
//  The program builds a feasible schedule using a deterministic
//  earliest‑start list scheduling rule.  At each step it chooses the
//  operation (next operation of a job) that can start the earliest,
//  ties are broken by smaller job index.  When an operation is scheduled
//  we record the job in the order list of the corresponding machine.
//  After all J·M operations are scheduled each machine's list is a
//  permutation of {0..J‑1}, which is exactly the required output.
//  The schedule is always feasible, therefore the produced machine
//  orders never contain cycles.
//
//  Complexity: O(J·M·J)  ( ≤ 1.3·10⁵ for the maximal test sizes).

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int J, M;
    if (!(cin >> J >> M)) return 0;

    // jobOps[j][k] = (machine, processing time) of the k-th operation of job j
    vector<vector<pair<int,long long>>> jobOps(J, vector<pair<int,long long>>(M));
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m; long long p;
            cin >> m >> p;
            jobOps[j][k] = {m, p};
        }
    }

    vector<int> nextIdx(J, 0);               // next operation index for each job
    vector<long long> jobReady(J, 0);        // time when the job becomes ready for its next operation
    vector<long long> machineAvail(M, 0);    // next free time of each machine
    vector<vector<int>> order(M);            // resulting order per machine

    const long long INF = (1LL<<62);
    int totalOps = J * M;
    int scheduled = 0;

    while (scheduled < totalOps) {
        long long bestStart = INF;
        int bestJob = -1;
        int bestMachine = -1;
        long long bestProc = 0;

        // Find the operation with minimal earliest start time
        for (int j = 0; j < J; ++j) {
            if (nextIdx[j] >= M) continue; // job finished
            auto [m, p] = jobOps[j][nextIdx[j]];
            long long start = max(jobReady[j], machineAvail[m]);
            if (start < bestStart || (start == bestStart && j < bestJob)) {
                bestStart = start;
                bestJob = j;
                bestMachine = m;
                bestProc = p;
            }
        }
        // Schedule the chosen operation
        order[bestMachine].push_back(bestJob);
        long long finish = bestStart + bestProc;
        jobReady[bestJob] = finish;
        machineAvail[bestMachine] = finish;
        ++nextIdx[bestJob];
        ++scheduled;
    }

    // Output M lines, each containing a permutation of 0..J-1
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << order[m][i];
        }
        if (m + 1 < M) cout << '\n';
    }
    return 0;
}

/****************************************************************************************
 * Job‑Shop Open Optimization – Heuristic Scheduler
 *
 * Algorithm
 * ----------
 * 1. Parse the instance. For every job store the sequence of machines and the
 *    processing times. Also build:
 *      - proc[j][m]   – processing time of job j on machine m
 *      - posInRoute[j][m] – index of machine m in job j’s route
 *      - totalWork[j] – sum of remaining processing times of job j
 *
 * 2. Construct a feasible schedule by a greedy “list‑scheduling’’ rule:
 *    While operations remain, consider every job’s next operation.
 *    Compute its earliest possible start = max(jobReady, machineReady).
 *    Choose the operation(s) with the minimum start time.
 *    Among those pick the job with the largest remaining work
 *    (ties are broken randomly).  Schedule it, update ready times and
 *    append the job index to the order of the used machine.
 *    This yields a feasible set of machine permutations and a makespan.
 *
 * 3. Repeatedly improve the solution by local search:
 *    Randomly pick a machine and an adjacent pair of jobs,
 *    swap them, and evaluate the makespan of the new orders.
 *    Evaluation is performed by simulating the earliest‑feasible schedule
 *    that respects the given machine orders (a simple priority‑queue‑free
 *    forward pass).  If the swap reduces the makespan it is kept,
 *    otherwise it is reverted.  The search runs until the time limit
 *    (≈1.9 s) expires.
 *
 * 4. Output the best permutation for each machine.
 *
 * The program is deterministic except for controlled randomness (fixed seed)
 * used to diversify tie‑breaking and the local‑search moves.
 *
 * Complexity
 * ----------
 *   Building a schedule: O(J·M·J) ≤ 6·10⁴ operations.
 *   Evaluation of a candidate order: O(J·M·M) ≤ 3·10⁴ operations.
 *   Both are easily fast enough for the given limits.
 *****************************************************************************************/

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int J, M;
    if (!(cin >> J >> M)) return 0;

    vector<vector<int>> jobMach(J, vector<int>(M));
    vector<vector<long long>> jobProc(J, vector<long long>(M));
    vector<vector<long long>> proc(J, vector<long long>(M, -1));
    vector<vector<int>> posInRoute(J, vector<int>(M, -1));
    vector<long long> totalWork(J, 0);

    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m; long long p;
            cin >> m >> p;
            jobMach[j][k] = m;
            jobProc[j][k] = p;
            proc[j][m] = p;
            posInRoute[j][m] = k;
            totalWork[j] += p;
        }
    }

    const long long INF = LLONG_MAX / 4;
    mt19937 rng(123456789);                     // fixed seed for reproducibility

    /* -------------------------------------------------------------
       Build a feasible schedule (greedy list scheduling) and record
       the machine orders.
       ------------------------------------------------------------- */
    auto buildSchedule = [&](mt19937& rng)
            -> pair<long long, vector<vector<int>>> {
        vector<long long> jobReady(J, 0);
        vector<long long> machineReady(M, 0);
        vector<int> nextIdx(J, 0);
        vector<long long> remain = totalWork;
        vector<vector<int>> order(M);
        order.assign(M, vector<int>());
        int opsLeft = J * M;

        while (opsLeft--) {
            long long minStart = INF;
            vector<int> cand;                     // jobs with minimal start
            // find minimal earliest start
            for (int j = 0; j < J; ++j) {
                int idx = nextIdx[j];
                if (idx == M) continue;           // all ops done
                int m = jobMach[j][idx];
                long long start = max(jobReady[j], machineReady[m]);
                if (start < minStart) {
                    minStart = start;
                    cand.clear();
                    cand.push_back(j);
                } else if (start == minStart) {
                    cand.push_back(j);
                }
            }
            // among those, pick job with largest remaining work (random tie)
            long long bestRem = -1;
            vector<int> bestCand;
            for (int j : cand) {
                if (remain[j] > bestRem) {
                    bestRem = remain[j];
                    bestCand.clear();
                    bestCand.push_back(j);
                } else if (remain[j] == bestRem) {
                    bestCand.push_back(j);
                }
            }
            int chosen = bestCand[rng() % bestCand.size()];

            int idx = nextIdx[chosen];
            int m = jobMach[chosen][idx];
            long long p = jobProc[chosen][idx];
            long long start = max(jobReady[chosen], machineReady[m]);
            long long finish = start + p;

            jobReady[chosen] = finish;
            machineReady[m] = finish;
            remain[chosen] -= p;
            order[m].push_back(chosen);
            ++nextIdx[chosen];
        }

        long long makespan = 0;
        for (long long t : jobReady) makespan = max(makespan, t);
        return {makespan, order};
    };

    /* -------------------------------------------------------------
       Evaluate a complete set of machine orders:
       simulate the earliest feasible schedule respecting those orders.
       ------------------------------------------------------------- */
    auto evaluate = [&](const vector<vector<int>>& order) -> long long {
        vector<int> pos(M, 0);                 // next index on each machine
        vector<int> nextIdx(J, 0);             // next operation index for each job
        vector<long long> jobReady(J, 0);
        vector<long long> machineReady(M, 0);
        int scheduled = 0;
        const int totalOps = J * M;
        long long makespan = 0;

        while (scheduled < totalOps) {
            long long bestStart = INF;
            int bestM = -1, bestJ = -1;
            for (int m = 0; m < M; ++m) {
                int i = pos[m];
                if (i >= J) continue;
                int j = order[m][i];
                // job must be ready for this machine (its next operation)
                if (posInRoute[j][m] != nextIdx[j]) continue;
                long long start = max(jobReady[j], machineReady[m]);
                if (start < bestStart) {
                    bestStart = start;
                    bestM = m;
                    bestJ = j;
                }
            }
            if (bestM == -1) return INF;        // deadlock → infeasible
            long long p = proc[bestJ][bestM];
            long long finish = bestStart + p;

            jobReady[bestJ] = finish;
            machineReady[bestM] = finish;
            ++pos[bestM];
            ++nextIdx[bestJ];
            ++scheduled;
            makespan = max(makespan, finish);
        }
        return makespan;
    };

    /* -------------------------------------------------------------
       Main optimisation loop (time‑bounded)
       ------------------------------------------------------------- */
    auto startTime = chrono::steady_clock::now();
    const double TOTAL_TIME = 1.9;            // seconds
    const double BUILD_TIME = 0.9;            // part allocated to construction

    long long bestMakespan = INF;
    vector<vector<int>> bestOrder;

    // Construct several initial schedules (randomised tie‑breaking)
    while (chrono::duration<double>(chrono::steady_clock::now() - startTime).count()
           < BUILD_TIME) {
        auto [ms, ord] = buildSchedule(rng);
        if (ms < bestMakespan) {
            bestMakespan = ms;
            bestOrder.swap(ord);
        }
    }

    // Fallback (should never be needed)
    if (bestOrder.empty()) {
        bestOrder.assign(M, vector<int>(J));
        for (int m = 0; m < M; ++m)
            for (int j = 0; j < J; ++j) bestOrder[m][j] = j;
        bestMakespan = evaluate(bestOrder);
    }

    // Local search: random adjacent swaps on machines
    while (chrono::duration<double>(chrono::steady_clock::now() - startTime).count()
           < TOTAL_TIME) {
        if (J < 2) break;
        int m = rng() % M;
        int i = rng() % (J - 1);
        swap(bestOrder[m][i], bestOrder[m][i + 1]);
        long long ms = evaluate(bestOrder);
        if (ms < bestMakespan) {
            bestMakespan = ms;                 // keep the improvement
        } else {
            swap(bestOrder[m][i], bestOrder[m][i + 1]); // revert
        }
    }

    /* -------------------------------------------------------------
       Output
       ------------------------------------------------------------- */
    for (int m = 0; m < M; ++m) {
        for (int j = 0; j < J; ++j) {
            if (j) cout << ' ';
            cout << bestOrder[m][j];
        }
        if (m + 1 < M) cout << '\n';
    }
    return 0;
}

/* 
   Job‑Shop scheduling – simple constructive heuristic.
   ----------------------------------------------------
   We simulate a non‑delay schedule: at each step we pick the
   operation that can start the earliest (max(job_ready,
   machine_ready)).  When several operations have the same
   earliest start we break ties using a secondary key.
   Several tie‑breaking rules are tried (LPT, SPT, longest
   remaining work, bottleneck‑machine first, random).  The
   best schedule (smallest makespan) found within the time
   limit is output as the required per‑machine job order.
*/

#include <bits/stdc++.h>
using namespace std;

struct Op {
    int machine;
    long long proc;
};

struct Result {
    long long makespan;
    vector<vector<int>> order; // per machine
};

Result runSchedule(const vector<vector<Op>>& jobs,
                   const vector<vector<long long>>& suffix,
                   int bottleneck,
                   int heuristic,               // 0:LPT,1:SPT,2:LR,3:Bottleneck,4:Random
                   uint64_t rngSeed) {
    int J = (int)jobs.size();
    int M = (int)jobs[0].size();

    vector<int> nextIdx(J, 0);
    vector<long long> jobReady(J, 0);
    vector<long long> machReady(M, 0);
    vector<vector<int>> order(M);
    for (int m = 0; m < M; ++m) order[m].reserve(J);

    mt19937_64 rng(rngSeed);

    const long long INF = (1LL << 60);

    for (int step = 0; step < J * M; ++step) {
        int bestJob = -1, bestMach = -1;
        long long bestStart = INF, bestProc = 0;
        long long bestSec1 = 0, bestSec2 = 0, bestSec3 = 0;

        for (int j = 0; j < J; ++j) {
            int idx = nextIdx[j];
            if (idx >= M) continue;
            const Op& op = jobs[j][idx];
            int m = op.machine;
            long long p = op.proc;
            long long start = jobReady[j] > machReady[m] ? jobReady[j] : machReady[m];

            long long sec1 = 0, sec2 = 0, sec3 = 0;
            long long remAfter = (idx + 1 < M) ? suffix[j][idx + 1] : 0;

            switch (heuristic) {
                case 0: // LPT
                    sec1 = -p;
                    sec2 = -remAfter;
                    break;
                case 1: // SPT
                    sec1 = p;
                    sec2 = -remAfter;
                    break;
                case 2: // Longest remaining
                    sec1 = -remAfter;
                    sec2 = -p;
                    break;
                case 3: // Prioritise bottleneck machine
                    sec1 = (m == bottleneck) ? 0LL : 1LL;
                    sec2 = -p;
                    sec3 = -remAfter;
                    break;
                case 4: // Random tie‑break
                    sec1 = (long long)rng();
                    sec2 = -p;
                    sec3 = -remAfter;
                    break;
            }

            bool better = false;
            if (start < bestStart) {
                better = true;
            } else if (start == bestStart) {
                if (sec1 < bestSec1) better = true;
                else if (sec1 == bestSec1) {
                    if (sec2 < bestSec2) better = true;
                    else if (sec2 == bestSec2) {
                        if (sec3 < bestSec3) better = true;
                        else if (sec3 == bestSec3 && j < bestJob) better = true;
                    }
                }
            }
            if (better) {
                bestStart = start;
                bestJob = j;
                bestMach = m;
                bestProc = p;
                bestSec1 = sec1;
                bestSec2 = sec2;
                bestSec3 = sec3;
            }
        }

        // schedule the selected operation
        long long finish = bestStart + bestProc;
        jobReady[bestJob] = finish;
        machReady[bestMach] = finish;
        order[bestMach].push_back(bestJob);
        ++nextIdx[bestJob];
    }

    long long makespan = 0;
    for (auto t : jobReady) makespan = max(makespan, t);

    Result res;
    res.makespan = makespan;
    res.order = std::move(order);
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int J, M;
    if (!(cin >> J >> M)) return 0;

    vector<vector<Op>> jobs(J, vector<Op>(M));
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m; long long p;
            cin >> m >> p;
            jobs[j][k] = {m, p};
        }
    }

    // suffix sums of processing times (remaining work)
    vector<vector<long long>> suffix(J, vector<long long>(M + 1, 0));
    for (int j = 0; j < J; ++j) {
        for (int i = M - 1; i >= 0; --i) {
            suffix[j][i] = suffix[j][i + 1] + jobs[j][i].proc;
        }
    }

    // machine loads to identify the bottleneck
    vector<long long> load(M, 0);
    for (int j = 0; j < J; ++j)
        for (int i = 0; i < M; ++i)
            load[jobs[j][i].machine] += jobs[j][i].proc;
    int bottleneck = 0;
    for (int m = 1; m < M; ++m)
        if (load[m] > load[bottleneck]) bottleneck = m;

    Result best;
    best.makespan = (1LL << 60);

    // deterministic heuristics
    for (int h = 0; h <= 3; ++h) {
        Result cur = runSchedule(jobs, suffix, bottleneck, h, 0);
        if (cur.makespan < best.makespan) best = std::move(cur);
    }

    // randomised search – run while time permits
    const double TIME_LIMIT = 0.90; // seconds
    auto startTime = chrono::steady_clock::now();
    uint64_t iter = 0;
    while (true) {
        auto now = chrono::steady_clock::now();
        double elapsed = chrono::duration<double>(now - startTime).count();
        if (elapsed >= TIME_LIMIT) break;
        uint64_t seed = 987654321ULL + iter;
        Result cur = runSchedule(jobs, suffix, bottleneck, 4, seed);
        if (cur.makespan < best.makespan) best = std::move(cur);
        ++iter;
    }

    // output the best ordering
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            cout << best.order[m][i];
            if (i + 1 != J) cout << ' ';
        }
        if (m + 1 != M) cout << '\n';
    }
    return 0;
}

/*
 * Job Shop Scheduling – heuristic construction + local search.
 * ---------------------------------------------------------
 * 1) Read the job routes and processing times.
 *    For each job j and each machine m we store the index k of the
 *    operation (j,k) that uses m (opPos[j][m]).
 *
 * 2) Build an initial feasible schedule by a greedy “earliest start”
 *    dispatch: repeatedly schedule the ready operation with the smallest
 *    possible start time (ties broken by shorter processing time).
 *    The order in which operations are scheduled on each machine gives
 *    an initial permutation for that machine.
 *
 * 3) Evaluate a set of permutations by constructing the disjunctive graph:
 *    - Nodes are all operations (j,k).
 *    - Fixed arcs: job predecessor (j,k) → (j,k+1).
 *    - Machine arcs come from the current permutations.
 *    Longest‑path computation (topological DP) yields the makespan and
 *    also detects cycles (infeasible permutations).
 *
 * 4) Local improvement:
 *    a) Steepest‑descent hill climbing on adjacent swaps:
 *       repeatedly examine all adjacent swaps on every machine,
 *       keep the best feasible improvement and apply it.
 *    b) If time permits, run a short simulated‑annealing phase that
 *       performs random swaps (any two positions) and accepts worsening
 *       moves with a temperature schedule.
 *
 * 5) Output the best permutation found.
 *
 * The algorithm works in O(N) (N = J·M) per evaluation (≈1250 operations)
 * and fits easily into the 1‑second limit, delivering a feasible schedule
 * that is usually much better than the trivial baseline.
 */

#include <bits/stdc++.h>
using namespace std;

struct Solver {
    int J, M, N;                     // jobs, machines, total operations
    vector<vector<int>> jobMach;    // jobMach[j][k] = machine of k-th op of job j
    vector<vector<int>> jobProc;    // processing times
    vector<vector<int>> opPos;      // opPos[j][m] = index k where job j uses machine m
    vector<int> proc;               // processing time of each node (size N)
    vector<int> jobSucc, jobPrev;   // static job successors / predecessors (node ids)
    // auxiliary arrays reused in every evaluation
    vector<int> machinePos, machineSucc, indeg;
    vector<long long> start;
    vector<int> q;

    // node id = j * M + k
    inline int nodeId(int job, int mach) const {
        return job * M + opPos[job][mach];
    }

    // evaluate a given permutation set.
    // Returns true if feasible and sets makespan, otherwise false.
    bool evaluate(const vector<vector<int>>& perm, long long& makespan) {
        // reset machine position / successor info
        fill(machinePos.begin(), machinePos.begin() + N, -1);
        fill(machineSucc.begin(), machineSucc.begin() + N, -1);

        // fill machine ordering
        for (int m = 0; m < M; ++m) {
            const vector<int>& order = perm[m];
            for (int pos = 0; pos < J; ++pos) {
                int job = order[pos];
                int nid = nodeId(job, m);
                machinePos[nid] = pos;
                if (pos + 1 < J) {
                    int nxtJob = order[pos + 1];
                    int succ = nodeId(nxtJob, m);
                    machineSucc[nid] = succ;
                }
            }
        }

        // indegree & earliest start initialisation
        for (int v = 0; v < N; ++v) {
            int inde = 0;
            if (jobPrev[v] != -1) ++indeg[v] = 1, inde = 1;
            if (machinePos[v] > 0) ++indeg[v];
            indeg[v] = inde;
            start[v] = 0;
        }

        int qh = 0, qt = 0;
        for (int v = 0; v < N; ++v) if (indeg[v] == 0) q[qt++] = v;

        long long maxFin = 0;
        int processed = 0;
        while (qh < qt) {
            int u = q[qh++];
            ++processed;
            long long fin = start[u] + proc[u];
            if (fin > maxFin) maxFin = fin;

            int v = jobSucc[u];
            if (v != -1) {
                if (start[v] < fin) start[v] = fin;
                if (--indeg[v] == 0) q[qt++] = v;
            }
            v = machineSucc[u];
            if (v != -1) {
                if (start[v] < fin) start[v] = fin;
                if (--indeg[v] == 0) q[qt++] = v;
            }
        }

        if (processed != N) return false; // cycle detected
        makespan = maxFin;
        return true;
    }

    // greedy dispatch to obtain an initial feasible permutation
    vector<vector<int>> construct_initial() {
        vector<vector<int>> perm(M);
        vector<long long> readyMach(M, 0), readyJob(J, 0);
        vector<int> curOp(J, 0);
        int done = 0;
        while (done < N) {
            long long bestStart = LLONG_MAX;
            long long bestProc = LLONG_MAX;
            int bestJob = -1;
            for (int j = 0; j < J; ++j) {
                if (curOp[j] >= M) continue;
                int k = curOp[j];
                int m = jobMach[j][k];
                long long st = max(readyJob[j], readyMach[m]);
                long long p = jobProc[j][k];
                if (st < bestStart || (st == bestStart && p < bestProc)) {
                    bestStart = st;
                    bestProc = p;
                    bestJob = j;
                }
            }
            int j = bestJob;
            int k = curOp[j];
            int m = jobMach[j][k];
            long long p = jobProc[j][k];
            long long fin = bestStart + p;
            readyJob[j] = fin;
            readyMach[m] = fin;
            perm[m].push_back(j);
            ++curOp[j];
            ++done;
        }
        return perm;
    }

    void solve() {
        ios::sync_with_stdio(false);
        cin.tie(nullptr);
        if (!(cin >> J >> M)) return;
        jobMach.assign(J, vector<int>(M));
        jobProc.assign(J, vector<int>(M));
        opPos.assign(J, vector<int>(M, -1));
        for (int j = 0; j < J; ++j) {
            for (int k = 0; k < M; ++k) {
                int m, p;
                cin >> m >> p;
                jobMach[j][k] = m;
                jobProc[j][k] = p;
                opPos[j][m] = k;
            }
        }
        N = J * M;
        proc.assign(N, 0);
        jobSucc.assign(N, -1);
        jobPrev.assign(N, -1);
        for (int j = 0; j < J; ++j) {
            for (int k = 0; k < M; ++k) {
                int nid = j * M + k;
                proc[nid] = jobProc[j][k];
                if (k + 1 < M) jobSucc[nid] = j * M + (k + 1);
                if (k > 0) jobPrev[nid] = j * M + (k - 1);
            }
        }

        // auxiliary vectors
        machinePos.assign(N, -1);
        machineSucc.assign(N, -1);
        indeg.assign(N, 0);
        start.assign(N, 0);
        q.assign(N, 0);

        // initial solution
        vector<vector<int>> curPerm = construct_initial();
        long long curMakespan;
        bool ok = evaluate(curPerm, curMakespan);
        if (!ok) {
            // Should never happen
            curMakespan = LLONG_MAX;
        }

        vector<vector<int>> bestPerm = curPerm;
        long long bestMakespan = curMakespan;

        // time control
        auto startTime = chrono::steady_clock::now();
        const double TOTAL_TIME = 0.95;           // seconds
        const double HC_TIME = 0.5 * TOTAL_TIME; // allocate half to hill climbing

        // ---------- Hill Climbing (adjacent swaps) ----------
        bool improved = true;
        while (improved) {
            improved = false;
            long long bestLocalMakespan = curMakespan;
            int bestM = -1, bestPos = -1;

            for (int m = 0; m < M && !improved; ++m) {
                for (int i = 0; i < J - 1; ++i) {
                    swap(curPerm[m][i], curPerm[m][i + 1]);
                    long long newC;
                    bool feas = evaluate(curPerm, newC);
                    if (feas && newC < bestLocalMakespan) {
                        bestLocalMakespan = newC;
                        bestM = m;
                        bestPos = i;
                    }
                    swap(curPerm[m][i], curPerm[m][i + 1]); // revert

                    if (chrono::duration<double>(chrono::steady_clock::now() - startTime).count() > HC_TIME)
                        break;
                }
                if (chrono::duration<double>(chrono::steady_clock::now() - startTime).count() > HC_TIME)
                    break;
            }

            if (bestM != -1 && bestLocalMakespan < curMakespan) {
                swap(curPerm[bestM][bestPos], curPerm[bestM][bestPos + 1]);
                curMakespan = bestLocalMakespan;
                improved = true;
                if (curMakespan < bestMakespan) {
                    bestMakespan = curMakespan;
                    bestPerm = curPerm;
                }
            }
        }

        // ---------- Simulated Annealing (random swaps) ----------
        std::mt19937_64 rng(123456789);
        uniform_int_distribution<int> distM(0, M - 1);
        uniform_int_distribution<int> distJ(0, J - 1);
        uniform_real_distribution<double> distReal(0.0, 1.0);

        double T = max(1.0, (double)curMakespan * 0.5);
        long long iterations = 0;
        while (chrono::duration<double>(chrono::steady_clock::now() - startTime).count() < TOTAL_TIME) {
            int m = distM(rng);
            int i = distJ(rng);
            int j = distJ(rng);
            if (i == j) continue;
            if (i > j) swap(i, j);
            swap(curPerm[m][i], curPerm[m][j]);

            long long newC;
            bool feas = evaluate(curPerm, newC);
            if (feas) {
                long long delta = curMakespan - newC; // positive = improvement
                bool accept = false;
                if (delta > 0) {
                    accept = true;
                } else {
                    double prob = exp((double)delta / T);
                    if (distReal(rng) < prob) accept = true;
                }
                if (accept) {
                    curMakespan = newC;
                    if (newC < bestMakespan) {
                        bestMakespan = newC;
                        bestPerm = curPerm;
                    }
                } else {
                    swap(curPerm[m][i], curPerm[m][j]); // revert
                }
            } else {
                swap(curPerm[m][i], curPerm[m][j]); // revert (infeasible)
            }

            ++iterations;
            if (iterations % 1000 == 0) {
                T *= 0.995;
                if (T < 1e-3) T = 1e-3;
            }
        }

        // ---------- Output ----------
        for (int m = 0; m < M; ++m) {
            for (int i = 0; i < J; ++i) {
                if (i) cout << ' ';
                cout << bestPerm[m][i];
            }
            if (m + 1 < M) cout << '\n';
        }
    }
};

int main() {
    Solver s;
    s.solve();
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

/* -------------------------------------------------------------
   Global data (filled once after reading the instance)
   ------------------------------------------------------------- */
int J, M;                               // number of jobs / machines
vector<vector<int>>    route;           // route[j][k]   – machine of k‑th op of job j
vector<vector<long long>> proc;        // processing time
vector<vector<int>>    jobPosIdx;      // jobPosIdx[j][m] – index k where job j uses machine m
vector<long long>      procFlat;       // linearised processing times, id = j*M + k
vector<vector<long long>> suffix;      // suffix[j][k] = sum_{t=k}^{M-1} proc[j][t]

/* -------------------------------------------------------------
   longest path (makespan) for a given set of machine orders
   ------------------------------------------------------------- */
long long makespan(const vector<vector<int>>& order) {
    const int N = J * M;
    static vector<int> indeg; indeg.assign(N, 0);
    static vector<long long> start; start.assign(N, 0);
    static vector<int> machineSucc; machineSucc.assign(N, -1);

    // job arcs: each operation (except the first) has one incoming arc
    for (int j = 0; j < J; ++j)
        for (int k = 0; k < M; ++k)
            indeg[j * M + k] = (k == 0 ? 0 : 1);

    // machine arcs, also fill indegrees
    for (int m = 0; m < M; ++m) {
        const auto& seq = order[m];
        for (int p = 0; p + 1 < J; ++p) {
            int ja = seq[p];   int ka = jobPosIdx[ja][m];
            int jb = seq[p+1]; int kb = jobPosIdx[jb][m];
            int u = ja * M + ka;
            int v = jb * M + kb;
            machineSucc[u] = v;
            ++indeg[v];
        }
    }

    // Kahn + DP (longest path)
    vector<int> q; q.reserve(N);
    for (int i = 0; i < N; ++i)
        if (indeg[i] == 0) q.push_back(i);

    long long best = 0;
    int processed = 0;
    while (!q.empty()) {
        int u = q.back(); q.pop_back(); ++processed;
        long long fin = start[u] + procFlat[u];
        if (fin > best) best = fin;

        // job successor
        int k = u % M;
        if (k + 1 < M) {
            int v = u + 1;
            if (start[v] < fin) start[v] = fin;
            if (--indeg[v] == 0) q.push_back(v);
        }
        // machine successor
        int v = machineSucc[u];
        if (v != -1) {
            if (start[v] < fin) start[v] = fin;
            if (--indeg[v] == 0) q.push_back(v);
        }
    }
    if (processed != N) return LLONG_MAX;          // cycle → infeasible
    return best;
}

/* -------------------------------------------------------------
   Build one random feasible schedule (Giffler‑Thompson style)
   ------------------------------------------------------------- */
mt19937 rng(1234567);    // deterministic seed, still gives many different schedules

pair<vector<vector<int>>, long long> randomSchedule() {
    vector<vector<int>> order(M);
    vector<int>    pos(J, 0);
    vector<long long> jobReady(J, 0), machReady(M, 0);

    const int total = J * M;
    for (int step = 0; step < total; ++step) {
        long long bestFin = LLONG_MAX;
        vector<int> cand; cand.reserve(J);

        // scan all jobs, find minimal earliest finishing time
        for (int j = 0; j < J; ++j) if (pos[j] < M) {
            int   m = route[j][pos[j]];
            long long p = proc[j][pos[j]];
            long long st = max(jobReady[j], machReady[m]);
            long long fin = st + p;
            if (fin < bestFin) {
                bestFin = fin;
                cand.clear(); cand.push_back(j);
            } else if (fin == bestFin) {
                cand.push_back(j);
            }
        }

        // among candidates keep those with maximal remaining work
        long long bestRem = -1;
        vector<int> bestCand;
        for (int j : cand) {
            long long rem = suffix[j][pos[j]];
            if (rem > bestRem) {
                bestRem = rem;
                bestCand.clear(); bestCand.push_back(j);
            } else if (rem == bestRem) {
                bestCand.push_back(j);
            }
        }
        int chosen = bestCand[rng() % bestCand.size()];

        // schedule the chosen operation
        int   k = pos[chosen];
        int   m = route[chosen][k];
        long long p = proc[chosen][k];
        long long st = max(jobReady[chosen], machReady[m]);
        long long fin = st + p;

        jobReady[chosen] = fin;
        machReady[m] = fin;
        order[m].push_back(chosen);
        ++pos[chosen];
    }
    long long C = makespan(order);                // value for comparison
    return {order, C};
}

/* -------------------------------------------------------------
   Main
   ------------------------------------------------------------- */
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> J >> M)) return 0;

    route.assign(J, vector<int>(M));
    proc.assign(J, vector<long long>(M));
    jobPosIdx.assign(J, vector<int>(M, -1));

    for (int j = 0; j < J; ++j) {
        for (int i = 0; i < M; ++i) {
            int m; long long p;
            cin >> m >> p;
            route[j][i] = m;
            proc[j][i] = p;
            jobPosIdx[j][m] = i;
        }
    }

    // flatten processing times
    procFlat.assign(J * M, 0);
    for (int j = 0; j < J; ++j)
        for (int k = 0; k < M; ++k)
            procFlat[j * M + k] = proc[j][k];

    // suffix sums (remaining work) – used for tie breaking
    suffix.assign(J, vector<long long>(M + 1, 0));
    for (int j = 0; j < J; ++j) {
        for (int k = M - 1; k >= 0; --k)
            suffix[j][k] = suffix[j][k + 1] + proc[j][k];
    }

    // -----------------------------------------------------------------
    // baseline: identity order on every machine (always feasible)
    vector<vector<int>> bestOrder(M, vector<int>(J));
    for (int m = 0; m < M; ++m)
        for (int j = 0; j < J; ++j) bestOrder[m][j] = j;

    long long bestC = makespan(bestOrder);

    // -----------------------------------------------------------------
    // multi‑start random schedules
    const double TOTAL_TIME = 0.94;                     // seconds
    const double LOCAL_TIME = 0.04;                     // reserve time for hill climbing
    auto start = chrono::steady_clock::now();

    while (true) {
        auto now = chrono::steady_clock::now();
        double used = chrono::duration<double>(now - start).count();
        if (used + LOCAL_TIME >= TOTAL_TIME) break;    // leave time for local search

        auto [ord, C] = randomSchedule();
        if (C < bestC) {
            bestC = C;
            bestOrder = std::move(ord);
        }
    }

    // -----------------------------------------------------------------
    // simple hill climbing: adjacent swaps on each machine
    while (true) {
        auto now = chrono::steady_clock::now();
        double used = chrono::duration<double>(now - start).count();
        if (used >= TOTAL_TIME) break;

        bool improved = false;
        for (int m = 0; m < M && !improved; ++m) {
            for (int p = 0; p + 1 < J && !improved; ++p) {
                swap(bestOrder[m][p], bestOrder[m][p + 1]);
                long long C = makespan(bestOrder);
                if (C < bestC) {
                    bestC = C;
                    improved = true;               // keep the swap
                } else {
                    swap(bestOrder[m][p], bestOrder[m][p + 1]); // revert
                }
            }
        }
        if (!improved) break;
    }

    // -----------------------------------------------------------------
    // output
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << bestOrder[m][i];
        }
        cout << '\n';
    }
    return 0;
}

/*
 * Job Shop Scheduling – simple yet effective heuristic.
 *
 * 1. Build a feasible schedule by repeatedly scheduling the ready operation
 *    with the earliest possible start time (ties broken by shortest processing).
 *    While doing this we record, for each machine, the order in which jobs are
 *    processed – this gives a valid permutation for the output.
 *
 * 2. Compute the makespan of a given set of machine orders by longest‑path
 *    DP on the disjunctive graph (job arcs + machine arcs).  Detect cycles
 *    (infeasible orders) via Kahn topological sort.
 *
 * 3. Local improvement:
 *      – deterministic pass: try every adjacent swap on every machine,
 *        keep the swap if it reduces the makespan.
 *      – stochastic hill‑climbing: while time permits repeatedly pick a random
 *        machine and two random positions, swap them and keep the change only
 *        if it improves the makespan.
 *
 * The algorithm runs well within the 1 s limit for the official sizes
 * (J≈50, M≈25, ≤1250 operations) and produces a competitive schedule.
 */

#include <bits/stdc++.h>
using namespace std;

int J, M;                                      // number of jobs and machines
vector<vector<int>> jobMach;                   // jobMach[j][k] = machine of k‑th operation of job j
vector<vector<long long>> jobProc;             // jobProc[j][k] = processing time of that operation
vector<vector<int>> stepIdx;                   // stepIdx[j][m] = step index of machine m in job j (‑1 if not used)

/*---------------------------------------------------------------*/
/* Compute makespan for a given machine order permutation.
   Returns a very large value if the orientation creates a cycle. */
long long computeMakespan(const vector<vector<int>>& order) {
    const long long INF = (1LL<<60);
    int N = J * M;                     // total number of operations
    vector<int> indeg(N, 0);
    vector<long long> dp(N, 0);
    vector<vector<int>> adj(N);

    // job precedence arcs
    for (int j = 0; j < J; ++j) {
        for (int s = 0; s < M - 1; ++s) {
            int u = j * M + s;
            int v = j * M + s + 1;
            adj[u].push_back(v);
            ++indeg[v];
        }
    }

    // machine arcs according to the given order
    for (int m = 0; m < M; ++m) {
        const auto& seq = order[m];
        for (int i = 0; i < J - 1; ++i) {
            int ja = seq[i];
            int jb = seq[i + 1];
            int sa = stepIdx[ja][m];
            int sb = stepIdx[jb][m];
            int u = ja * M + sa;
            int v = jb * M + sb;
            adj[u].push_back(v);
            ++indeg[v];
        }
    }

    // topological DP (Kahn)
    queue<int> q;
    for (int i = 0; i < N; ++i)
        if (indeg[i] == 0) q.push(i);

    int processed = 0;
    long long makespan = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        ++processed;
        long long finish = dp[u] + jobProc[u / M][u % M];
        makespan = max(makespan, finish);
        for (int v : adj[u]) {
            if (dp[v] < finish) dp[v] = finish;
            if (--indeg[v] == 0) q.push(v);
        }
    }

    if (processed < N) return INF;            // cycle → infeasible
    return makespan;
}

/*---------------------------------------------------------------*/
/* Produce an initial feasible machine order by greedy list scheduling. */
vector<vector<int>> initialSchedule() {
    vector<int> idx(J, 0);                     // next operation index for each job
    vector<long long> jobReady(J, 0);          // completion time of last scheduled op of each job
    vector<long long> machAvail(M, 0);         // when each machine becomes free
    vector<vector<int>> order(M);              // resulting machine orders

    int totalOps = J * M;
    for (int scheduled = 0; scheduled < totalOps; ++scheduled) {
        long long bestStart = LLONG_MAX;
        long long bestProc  = LLONG_MAX;
        int bestJob = -1;

        // choose the ready operation with smallest earliest start (ties: shortest proc)
        for (int j = 0; j < J; ++j) {
            int s = idx[j];
            if (s >= M) continue;
            int mach = jobMach[j][s];
            long long proc = jobProc[j][s];
            long long start = max(jobReady[j], machAvail[mach]);
            if (start < bestStart || (start == bestStart && proc < bestProc)) {
                bestStart = start;
                bestProc  = proc;
                bestJob   = j;
            }
        }

        // schedule the chosen operation
        int s = idx[bestJob];
        int mach = jobMach[bestJob][s];
        long long proc = jobProc[bestJob][s];
        long long start = max(jobReady[bestJob], machAvail[mach]);
        long long finish = start + proc;

        order[mach].push_back(bestJob);
        jobReady[bestJob] = finish;
        machAvail[mach] = finish;
        ++idx[bestJob];
    }
    return order;
}

/*---------------------------------------------------------------*/
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> J >> M)) return 0;

    jobMach.assign(J, vector<int>(M));
    jobProc.assign(J, vector<long long>(M));
    stepIdx.assign(J, vector<int>(M, -1));

    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m; long long p;
            cin >> m >> p;
            jobMach[j][k] = m;
            jobProc[j][k] = p;
            stepIdx[j][m] = k;
        }
    }

    // 1) build an initial feasible schedule
    vector<vector<int>> curOrder = initialSchedule();
    long long bestMakespan = computeMakespan(curOrder);
    vector<vector<int>> bestOrder = curOrder;

    // 2) deterministic local improvement (adjacent swaps)
    bool improved = true;
    while (improved) {
        improved = false;
        for (int m = 0; m < M; ++m) {
            for (int i = 0; i < J - 1; ++i) {
                swap(curOrder[m][i], curOrder[m][i + 1]);
                long long mk = computeMakespan(curOrder);
                if (mk < bestMakespan) {
                    bestMakespan = mk;
                    bestOrder = curOrder;
                    improved = true;
                } else {
                    swap(curOrder[m][i], curOrder[m][i + 1]); // revert
                }
            }
        }
    }

    // 3) stochastic hill climbing within the remaining time budget
    const double TIME_LIMIT = 0.90;  // seconds
    auto startTime = chrono::steady_clock::now();
    std::mt19937 rng(123456789);
    std::uniform_int_distribution<int> distM(0, M - 1);
    std::uniform_int_distribution<int> distJ(0, J - 1);

    curOrder = bestOrder; // start random search from current best
    while (true) {
        double elapsed = chrono::duration<double>(chrono::steady_clock::now() - startTime).count();
        if (elapsed > TIME_LIMIT) break;
        if (J < 2) break;

        int m = distM(rng);
        int i = distJ(rng);
        int j = distJ(rng);
        if (i == j) continue;
        swap(curOrder[m][i], curOrder[m][j]);
        long long mk = computeMakespan(curOrder);
        if (mk < bestMakespan) {
            bestMakespan = mk;
            bestOrder = curOrder;
        } else {
            swap(curOrder[m][i], curOrder[m][j]); // revert
        }
    }

    // Output the best found machine orders
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << bestOrder[m][i];
        }
        cout << '\n';
    }
    return 0;
}

/*
 * Job Shop Scheduling – heuristic constructive + local search
 *
 * 1. Read the jobs (machine order + processing times).
 * 2. Build a greedy list‑schedule:
 *      repeatedly schedule the operation which can start the earliest
 *      (ties broken by larger processing time).  The order in which a
 *      machine's operations are scheduled forms a feasible permutation.
 * 3. Evaluate a schedule via longest‑path in the disjunctive graph
 *    (topological DP).  This is exact and also detects cycles.
 * 4. Improve the schedule:
 *      – deterministic hill climbing with all adjacent swaps on every machine,
 *        accepting any improving swap;
 *      – afterwards, perform random swaps while time permits (fixed seed,
 *        deterministic).
 * 5. Output the best permutation found for each machine.
 *
 * The algorithm runs in O(N) per evaluation (N = J·M ≤ 1250) and fits easily
 * into the 1 s limit, yet produces a schedule much better than a naïve baseline.
 */

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL << 60);
const double TIME_LIMIT = 0.94;          // seconds, a bit below the limit

// Global data (filled once)
int J, M, N;                              // jobs, machines, total operations
vector<vector<int>> job_machine;          // job_machine[j][k] = machine of k‑th op of job j
vector<vector<int>> job_proc;             // processing times
vector<vector<int>> pos_in_job;           // pos_in_job[j][m] = step index of machine m in job j
vector<ll> proc_node;                     // processing time per node id = j*M + k
vector<int> job_succ;                     // node → next operation of the same job (or -1)

// ------------------------------------------------------------------
// Compute makespan for a given set of machine orders.
// Returns INF if the induced graph has a cycle (infeasible).
ll computeMakespan(const vector<vector<int>>& order) {
    static vector<int> indeg;
    static vector<int> mach_succ;
    indeg.assign(N, 0);
    mach_succ.assign(N, -1);

    // job predecessor contributes 1 indegree to each non‑first operation
    for (int id = 0; id < N; ++id) {
        int step = id % M;
        if (step > 0) indeg[id] = 1;
    }

    // machine arcs
    for (int m = 0; m < M; ++m) {
        const auto& seq = order[m];
        for (int i = 0; i + 1 < (int)seq.size(); ++i) {
            int ja = seq[i];
            int jb = seq[i + 1];
            int step_a = pos_in_job[ja][m];
            int step_b = pos_in_job[jb][m];
            int node_a = ja * M + step_a;
            int node_b = jb * M + step_b;
            mach_succ[node_a] = node_b;
            ++indeg[node_b];
        }
    }

    // topological longest‑path DP
    vector<ll> start(N, 0);
    deque<int> q;
    for (int i = 0; i < N; ++i)
        if (indeg[i] == 0) q.push_back(i);

    int processed = 0;
    ll makespan = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop_front();
        ++processed;
        ll fin = start[u] + proc_node[u];
        makespan = max(makespan, fin);

        int v = job_succ[u];
        if (v != -1) {
            if (start[v] < fin) start[v] = fin;
            if (--indeg[v] == 0) q.push_back(v);
        }
        v = mach_succ[u];
        if (v != -1) {
            if (start[v] < fin) start[v] = fin;
            if (--indeg[v] == 0) q.push_back(v);
        }
    }
    if (processed != N) return INF;      // cycle -> infeasible
    return makespan;
}

// ------------------------------------------------------------------
// Greedy list scheduling (earliest‑start rule) – builds a feasible order.
vector<vector<int>> constructInitialOrder() {
    vector<vector<int>> order(M);
    vector<int> nextStep(J, 0);
    vector<ll> jobReady(J, 0), machineAvail(M, 0);
    int remaining = J * M;

    while (remaining) {
        ll bestEst = 0;
        int bestJob = -1;
        for (int j = 0; j < J; ++j) {
            int step = nextStep[j];
            if (step == M) continue;                 // job finished
            int m = job_machine[j][step];
            ll est = max(jobReady[j], machineAvail[m]);
            if (bestJob == -1 || est < bestEst ||
               (est == bestEst && job_proc[j][step] > job_proc[bestJob][nextStep[bestJob]])) {
                bestJob = j;
                bestEst = est;
            }
        }
        int step = nextStep[bestJob];
        int m = job_machine[bestJob][step];
        ll start = bestEst;
        ll fin = start + job_proc[bestJob][step];
        order[m].push_back(bestJob);
        jobReady[bestJob] = fin;
        machineAvail[m] = fin;
        ++nextStep[bestJob];
        --remaining;
    }
    return order;
}

// ------------------------------------------------------------------
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> J >> M)) return 0;
    N = J * M;

    job_machine.assign(J, vector<int>(M));
    job_proc.assign(J, vector<int>(M));
    pos_in_job.assign(J, vector<int>(M, -1));

    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m, p;
            cin >> m >> p;
            job_machine[j][k] = m;
            job_proc[j][k] = p;
            pos_in_job[j][m] = k;
        }
    }

    // Pre‑compute per‑node data
    proc_node.assign(N, 0);
    job_succ.assign(N, -1);
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int id = j * M + k;
            proc_node[id] = job_proc[j][k];
            if (k + 1 < M) job_succ[id] = id + 1;
        }
    }

    // ------------------------------------------------------------------
    // Phase 1 – construct an initial feasible schedule
    vector<vector<int>> order = constructInitialOrder();
    ll bestMake = computeMakespan(order);
    vector<vector<int>> bestOrder = order;

    // ------------------------------------------------------------------
    // Phase 2 – deterministic hill climbing (adjacent swaps)
    auto start_time = chrono::steady_clock::now();
    bool improved = true;
    while (improved) {
        improved = false;
        for (int m = 0; m < M && !improved; ++m) {
            for (int i = 0; i + 1 < J; ++i) {
                swap(order[m][i], order[m][i + 1]);
                ll cur = computeMakespan(order);
                if (cur < bestMake) {
                    bestMake = cur;
                    bestOrder = order;
                    improved = true;                 // keep the swap
                } else {
                    swap(order[m][i], order[m][i + 1]); // revert
                }
                // time check
                if (chrono::duration<double>(chrono::steady_clock::now() - start_time).count() > TIME_LIMIT)
                    break;
            }
        }
        // keep the current (potentially improved) order for the next pass
    }

    // ------------------------------------------------------------------
    // Phase 3 – random swaps while time permits (fixed seed → deterministic)
    mt19937 rng(123456789);
    while (chrono::duration<double>(chrono::steady_clock::now() - start_time).count() < TIME_LIMIT) {
        int m = rng() % M;
        int i = rng() % J;
        int j = rng() % J;
        if (i == j) continue;
        swap(order[m][i], order[m][j]);
        ll cur = computeMakespan(order);
        if (cur < bestMake) {
            bestMake = cur;
            bestOrder = order;     // keep the improvement
        } else {
            swap(order[m][i], order[m][j]); // revert
        }
    }

    // ------------------------------------------------------------------
    // Output the best order found
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << bestOrder[m][i];
        }
        cout << '\n';
    }
    return 0;
}

/*
 * Job‑Shop Scheduling – constructive heuristic + local improvement
 *
 * 1) Generate many feasible schedules by a simple list‑scheduling rule:
 *    repeatedly pick a job whose next operation can start the earliest
 *    (earliest finishing time).  When several jobs tie, break the tie
 *    randomly.  While scheduling we record the order in which each machine
 *    processes the jobs – this yields a permutation for every machine.
 *
 * 2) Keep the best schedule (smallest makespan) found within the time limit.
 *
 * 3) Improve it by a hill‑climbing neighbourhood: try swapping each pair of
 *    adjacent jobs on every machine.  The new makespan is evaluated by a
 *    longest‑path computation on the corresponding disjunctive graph.
 *    Accept a swap only if it keeps the schedule feasible and strictly
 *    reduces the makespan.  Continue until no improving swap exists or the
 *    time budget expires.
 *
 * The program runs completely within the given limits and produces a feasible
 * set of permutations.  It is deterministic except for a fixed random seed.
 */

#include <bits/stdc++.h>
using namespace std;

int J, M;                                 // number of jobs / machines
vector<vector<int>> jobMach;              // jobMach[j][k] = machine of k‑th operation of job j
vector<vector<long long>> jobDur;         // processing time
vector<vector<int>> posOnJob;             // posOnJob[j][m] = index k of machine m in job j
vector<int> baseIndeg;                    // indegree contributed by job‑precedence arcs
int V;                                    // total number of operations (J*M)

// ------------------------------------------------------------------
// Compute makespan of a given set of machine orders.
// Returns {valid, makespan}.  If the orientation creates a cycle, valid = false.
pair<bool, long long> computeMakespan(const vector<vector<int>>& orders) {
    vector<int> indeg = baseIndeg;                     // copy base indegrees
    vector<int> machineNext(V, -1);                    // successor on the same machine

    // add machine arcs according to the given orders
    for (int m = 0; m < M; ++m) {
        const auto &ord = orders[m];
        for (int i = 0; i + 1 < (int)ord.size(); ++i) {
            int prevJob = ord[i];
            int curJob  = ord[i + 1];
            int nodePrev = prevJob * M + posOnJob[prevJob][m];
            int nodeCur  = curJob  * M + posOnJob[curJob ][m];
            ++indeg[nodeCur];
            machineNext[nodePrev] = nodeCur;
        }
    }

    vector<long long> earliest(V, 0);
    deque<int> q;
    for (int v = 0; v < V; ++v)
        if (indeg[v] == 0) q.push_back(v);

    long long makespan = 0;
    int processed = 0;
    while (!q.empty()) {
        int v = q.front(); q.pop_front();
        ++processed;
        int job = v / M;
        int idx = v % M;
        long long start = earliest[v];
        long long comp  = start + jobDur[job][idx];
        makespan = max(makespan, comp);

        // job successor
        if (idx + 1 < M) {
            int succ = v + 1;                 // because nodes of a job are contiguous
            if (earliest[succ] < comp) earliest[succ] = comp;
            if (--indeg[succ] == 0) q.push_back(succ);
        }
        // machine successor
        int ms = machineNext[v];
        if (ms != -1) {
            if (earliest[ms] < comp) earliest[ms] = comp;
            if (--indeg[ms] == 0) q.push_back(ms);
        }
    }
    if (processed != V) return {false, LLONG_MAX}; // cycle detected
    return {true, makespan};
}

// ------------------------------------------------------------------
// Generate one feasible schedule using the earliest‑finish rule.
// Returns the machine order and its makespan.
pair<vector<vector<int>>, long long> generateSchedule(mt19937 &rng) {
    vector<int> jobPos(J, 0);               // next operation index for each job
    vector<long long> jobReady(J, 0);       // when the next operation of a job can start
    vector<long long> machReady(M, 0);      // when a machine becomes free
    vector<vector<int>> orders(M);
    for (int m = 0; m < M; ++m) orders[m].reserve(J);

    long long makespan = 0;
    for (int step = 0; step < V; ++step) {
        long long bestFin = LLONG_MAX;
        vector<int> cand;
        // evaluate all jobs whose next operation is not yet scheduled
        for (int j = 0; j < J; ++j) {
            int pos = jobPos[j];
            if (pos == M) continue;                     // all operations done
            int m = jobMach[j][pos];
            long long start = max(jobReady[j], machReady[m]);
            long long fin   = start + jobDur[j][pos];
            if (fin < bestFin) {
                bestFin = fin;
                cand.clear();
                cand.push_back(j);
            } else if (fin == bestFin) {
                cand.push_back(j);
            }
        }
        // break ties randomly
        int chosen = cand[rng() % cand.size()];
        int pos = jobPos[chosen];
        int m   = jobMach[chosen][pos];
        long long start = max(jobReady[chosen], machReady[m]);
        long long fin   = start + jobDur[chosen][pos];
        // schedule it
        jobReady[chosen] = fin;
        machReady[m]     = fin;
        orders[m].push_back(chosen);
        jobPos[chosen]   = pos + 1;
        makespan = max(makespan, fin);
    }
    return {orders, makespan};
}

// ------------------------------------------------------------------
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> J >> M)) return 0;
    jobMach.assign(J, vector<int>(M));
    jobDur.assign(J, vector<long long>(M));
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m; long long p;
            cin >> m >> p;
            jobMach[j][k] = m;
            jobDur[j][k]  = p;
        }
    }

    // preprocessing: position of each machine inside each job
    posOnJob.assign(J, vector<int>(M));
    for (int j = 0; j < J; ++j)
        for (int k = 0; k < M; ++k)
            posOnJob[j][ jobMach[j][k] ] = k;

    V = J * M;
    baseIndeg.assign(V, 0);
    for (int j = 0; j < J; ++j)
        for (int k = 0; k < M; ++k)
            baseIndeg[j * M + k] = (k > 0 ? 1 : 0);    // one incoming arc from previous op of the same job

    // --------------------------------------------------------------
    // main search (time limited)
    mt19937 rng(123456789);                  // fixed seed -> deterministic
    const double TOTAL_TIME = 0.95;          // seconds
    auto startTime = chrono::steady_clock::now();

    vector<vector<int>> bestOrders;
    long long bestMakespan = LLONG_MAX;

    // --- random constructive phase ---
    while (true) {
        auto now = chrono::steady_clock::now();
        double elapsed = chrono::duration<double>(now - startTime).count();
        if (elapsed > TOTAL_TIME * 0.6) break;   // leave time for local improvement

        auto [orders, makespan] = generateSchedule(rng);
        if (makespan < bestMakespan) {
            bestMakespan = makespan;
            bestOrders = std::move(orders);
        }
    }

    // --- local improvement (adjacent swaps) ---
    vector<vector<int>> curOrders = bestOrders;
    long long curMakespan = bestMakespan;
    bool anyImprovement = true;
    while (anyImprovement) {
        anyImprovement = false;
        // optional random order of machines each pass
        vector<int> machIdx(M);
        iota(machIdx.begin(), machIdx.end(), 0);
        shuffle(machIdx.begin(), machIdx.end(), rng);

        for (int mm = 0; mm < M; ++mm) {
            int m = machIdx[mm];
            for (int i = 0; i + 1 < J; ++i) {
                swap(curOrders[m][i], curOrders[m][i + 1]);
                auto [valid, newMakespan] = computeMakespan(curOrders);
                if (valid && newMakespan < curMakespan) {
                    curMakespan = newMakespan;
                    bestMakespan = newMakespan;
                    bestOrders = curOrders;
                    anyImprovement = true;
                    // keep the swap and continue
                } else {
                    // revert
                    swap(curOrders[m][i], curOrders[m][i + 1]);
                }
            }
        }
        // time check
        auto now = chrono::steady_clock::now();
        if (chrono::duration<double>(now - startTime).count() > TOTAL_TIME) break;
    }

    // --------------------------------------------------------------
    // output best machine orders
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << bestOrders[m][i];
        }
        cout << '\n';
    }
    return 0;
}

/*
 * Job‑Shop scheduling – simple but effective heuristic.
 *
 * The program builds feasible machine orders by constructing an explicit schedule.
 * It repeatedly simulates a “earliest‑start” dispatching rule:
 *   – At each step consider the next not‑yet‑processed operation of every job.
 *   – Compute its earliest possible start = max(job_ready, machine_ready).
 *   – Choose the operation(s) with the minimum start time.
 *   – Break ties either randomly or by preferring the job with the largest
 *     remaining total processing time (a deterministic LPT‑like rule).
 *   – Schedule that operation, update the job and machine ready times,
 *     and record the job index in the corresponding machine’s order.
 *
 * The schedule is always feasible (it respects all precedence and machine
 * constraints), therefore the derived machine permutations are accepted.
 * Several schedules are generated (one deterministic baseline and many
 * random tie‑breakings). The schedule with the smallest makespan is kept and
 * its machine orders are printed.
 *
 * Complexity: O(iterations * J * M) with J ≤ 50, M ≤ 25, which easily fits
 * the 1‑second limit.
 */

#include <bits/stdc++.h>
using namespace std;

struct Op {
    int machine;
    long long proc;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int J, M;
    if (!(cin >> J >> M)) return 0;

    vector<vector<Op>> jobs(J, vector<Op>(M));
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m; long long p;
            cin >> m >> p;
            jobs[j][k] = {m, p};
        }
    }

    // Pre‑compute suffix sums of processing times for tie‑breaking (largest remaining work)
    vector<vector<long long>> suffix(J, vector<long long>(M + 1, 0));
    for (int j = 0; j < J; ++j) {
        for (int k = M - 1; k >= 0; --k) {
            suffix[j][k] = suffix[j][k + 1] + jobs[j][k].proc;
        }
    }

    // Helper: run one simulation, given a mode for tie breaking.
    // mode = 0 -> random, mode = 1 -> longest‑remaining deterministic.
    auto runSimulation = [&](int mode, mt19937 &rng) {
        vector<long long> jobReady(J, 0);
        vector<long long> machReady(M, 0);
        vector<int> nextOp(J, 0);
        vector<vector<int>> seq(M);
        int scheduled = 0;
        const int totalOps = J * M;

        while (scheduled < totalOps) {
            long long minStart = LLONG_MAX;
            // First pass: find the minimum possible start time.
            for (int j = 0; j < J; ++j) {
                int idx = nextOp[j];
                if (idx == M) continue;
                const Op &op = jobs[j][idx];
                long long st = max(jobReady[j], machReady[op.machine]);
                if (st < minStart) minStart = st;
            }
            // Collect all candidates attaining that start time.
            vector<int> cand;
            cand.reserve(J);
            for (int j = 0; j < J; ++j) {
                int idx = nextOp[j];
                if (idx == M) continue;
                const Op &op = jobs[j][idx];
                long long st = max(jobReady[j], machReady[op.machine]);
                if (st == minStart) cand.push_back(j);
            }

            int chosen;
            if (mode == 0) {                     // random tie breaking
                uniform_int_distribution<int> dist(0, (int)cand.size() - 1);
                chosen = cand[dist(rng)];
            } else {                             // deterministic: longest remaining work
                long long bestRem = -1;
                int bestJob = -1;
                for (int j : cand) {
                    long long rem = suffix[j][nextOp[j]]; // remaining processing including current
                    if (rem > bestRem || (rem == bestRem && j < bestJob)) {
                        bestRem = rem;
                        bestJob = j;
                    }
                }
                chosen = bestJob;
            }

            int opIdx = nextOp[chosen];
            const Op &op = jobs[chosen][opIdx];
            long long start = max(jobReady[chosen], machReady[op.machine]);
            long long finish = start + op.proc;

            jobReady[chosen] = finish;
            machReady[op.machine] = finish;
            ++nextOp[chosen];
            seq[op.machine].push_back(chosen);
            ++scheduled;
        }

        long long makespan = 0;
        for (long long t : jobReady) if (t > makespan) makespan = t;
        return make_pair(makespan, seq);
    };

    // Baseline schedule: jobs in natural order (0..J-1) – deterministic simple heuristic.
    long long bestMakespan = LLONG_MAX;
    vector<vector<int>> bestSeq;
    {
        auto naive = [&](int) {
            vector<long long> jobReady(J, 0), machReady(M, 0);
            vector<vector<int>> seq(M);
            for (int j = 0; j < J; ++j) {
                for (int k = 0; k < M; ++k) {
                    const Op &op = jobs[j][k];
                    long long start = max(jobReady[j], machReady[op.machine]);
                    long long finish = start + op.proc;
                    jobReady[j] = finish;
                    machReady[op.machine] = finish;
                    seq[op.machine].push_back(j);
                }
            }
            long long mk = 0;
            for (long long t : jobReady) mk = max(mk, t);
            return make_pair(mk, seq);
        };
        auto [mk, seq] = naive(0);
        bestMakespan = mk;
        bestSeq = move(seq);
    }

    // Randomised and deterministic runs.
    const int MAX_ITER = 500;                 // safe for given limits
    mt19937 baseRng(987654321);
    for (int iter = 0; iter < MAX_ITER; ++iter) {
        // Alternate between random and deterministic tie breaking.
        int mode = (iter % 5 == 0) ? 1 : 0;    // every 5th iteration: longest‑remaining rule
        mt19937 rng(baseRng());               // different seed each iteration
        auto [mk, seq] = runSimulation(mode, rng);
        if (mk < bestMakespan) {
            bestMakespan = mk;
            bestSeq = move(seq);
        }
    }

    // Output the best machine orders.
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << bestSeq[m][i];
        }
        cout << '\n';
    }
    return 0;
}

/*
   Job‑Shop scheduler – open optimisation
   -------------------------------------------------
   1️⃣  Build a feasible schedule by the classic active‑schedule
       generation scheme (global earliest start rule).  
   2️⃣  Derive the machine orders from that schedule.  
   3️⃣  Repeatedly improve the orders by simulated‑annealing moves
       (adjacent swap on a random machine).  
   4️⃣  The longest‑path DP (topological order) evaluates a schedule.
   -------------------------------------------------
   The program is fully deterministic (fixed RNG seed) and
   finishes well inside the 1 s limit.
*/

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (ll)9e18;

/* ---------- global data (read once) ---------- */
int J, M, N;                     // jobs, machines, N = J*M
vector<vector<int>> jobMach;    // jobMach[j][k] = machine of k‑th op of job j
vector<vector<int>> jobProc;    // processing time
vector<vector<int>> pos;        // pos[j][m] = index of machine m in job j

vector<int> machine_of;         // size N, machine of node id
vector<int> proc_of;            // size N, processing time of node id
vector<int> job_next;           // size N, id of next op of same job or -1

/* ---------- makespan of a given order ---------- */
ll makespan_of(const vector<vector<int>>& order, bool &feasible) {
    // indegree and machine successor
    static vector<int> indeg;
    static vector<int> machSucc;
    static vector<ll> est;
    indeg.assign(N, 0);
    machSucc.assign(N, -1);
    est.assign(N, 0);

    // job edges
    for (int u = 0; u < N; ++u) {
        int v = job_next[u];
        if (v != -1) indeg[v]++;
    }

    // machine edges
    for (int m = 0; m < M; ++m) {
        const auto &perm = order[m];
        for (int i = 0; i + 1 < J; ++i) {
            int uj = perm[i];
            int vj = perm[i + 1];
            int u = uj * M + pos[uj][m];
            int v = vj * M + pos[vj][m];
            machSucc[u] = v;
            indeg[v]++;
        }
    }

    // topological longest‑path DP
    deque<int> q;
    for (int i = 0; i < N; ++i)
        if (indeg[i] == 0) q.push_back(i);

    int processed = 0;
    ll makespan = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop_front();
        ++processed;
        ll finish = est[u] + proc_of[u];
        if (finish > makespan) makespan = finish;

        int v = job_next[u];
        if (v != -1) {
            if (finish > est[v]) est[v] = finish;
            if (--indeg[v] == 0) q.push_back(v);
        }
        v = machSucc[u];
        if (v != -1) {
            if (finish > est[v]) est[v] = finish;
            if (--indeg[v] == 0) q.push_back(v);
        }
    }

    feasible = (processed == N);
    return feasible ? makespan : INF;
}

/* ---------- produce an initial feasible order (active schedule) ---------- */
vector<vector<int>> initial_order(bool &feas, ll &cmax) {
    vector<int> curIdx(J, 0);
    vector<ll> readyJob(J, 0);
    vector<ll> readyMach(M, 0);
    vector<vector<int>> order(M);
    for (int m = 0; m < M; ++m) order[m].reserve(J);

    int total = J * M;
    for (int step = 0; step < total; ++step) {
        ll bestStart = INF;
        int bestJob = -1;
        int bestNode = -1;
        int bestMach = -1;
        // find ready operation with smallest earliest start
        for (int j = 0; j < J; ++j) {
            int idx = curIdx[j];
            if (idx >= M) continue;
            int node = j * M + idx;
            int m = machine_of[node];
            ll start = max(readyJob[j], readyMach[m]);
            if (start < bestStart ||
                (start == bestStart && proc_of[node] > proc_of[bestNode])) {
                bestStart = start;
                bestJob = j;
                bestNode = node;
                bestMach = m;
            }
        }
        // schedule it
        ll finish = bestStart + proc_of[bestNode];
        order[bestMach].push_back(bestJob);
        readyJob[bestJob] = finish;
        readyMach[bestMach] = finish;
        curIdx[bestJob]++;
    }

    // compute makespan to return it
    cmax = makespan_of(order, feas);
    return order;
}

/* ---------- local search (simulated annealing) ---------- */
vector<vector<int>> improve(const vector<vector<int>>& startOrder,
                            ll startCmax,
                            ml::mt19937_64 &rng) {
    vector<vector<int>> cur = startOrder;
    ll curC = startCmax;
    vector<vector<int>> best = cur;
    ll bestC = curC;

    // temperature parameters
    const double initTemp = max(1.0, (double)bestC);
    const double timeLimit = 0.94;            // seconds
    auto t0 = chrono::steady_clock::now();

    uniform_int_distribution<int> distM(0, M - 1);
    uniform_int_distribution<int> distPos(0, J - 2);
    uniform_real_distribution<double> dist01(0.0, 1.0);

    while (true) {
        double elapsed = chrono::duration<double>(chrono::steady_clock::now() - t0).count();
        if (elapsed >= timeLimit) break;
        double temperature = initTemp * max(0.0, 1.0 - elapsed / timeLimit);

        int m = distM(rng);
        int i = distPos(rng);
        int j = i + 1;                    // adjacent swap

        swap(cur[m][i], cur[m][j]);
        bool feas;
        ll newC = makespan_of(cur, feas);
        if (!feas) {
            swap(cur[m][i], cur[m][j]);   // revert
            continue;
        }

        bool accept = false;
        if (newC < curC) {
            accept = true;
        } else {
            double prob = exp(- (double)(newC - curC) / max(1.0, temperature));
            if (dist01(rng) < prob) accept = true;
        }

        if (accept) {
            curC = newC;
            if (newC < bestC) {
                bestC = newC;
                best = cur;
            }
        } else {
            swap(cur[m][i], cur[m][j]);   // revert
        }
    }
    return best;
}

/* ------------------- main ------------------- */
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    if (!(cin >> J >> M)) return 0;
    N = J * M;

    jobMach.assign(J, vector<int>(M));
    jobProc.assign(J, vector<int>(M));
    pos.assign(J, vector<int>(M));

    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m, p;
            cin >> m >> p;
            jobMach[j][k] = m;
            jobProc[j][k] = p;
            pos[j][m] = k;
        }
    }

    // flatten to node arrays
    machine_of.resize(N);
    proc_of.resize(N);
    job_next.resize(N, -1);
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int id = j * M + k;
            machine_of[id] = jobMach[j][k];
            proc_of[id] = jobProc[j][k];
            if (k + 1 < M) job_next[id] = id + 1;
        }
    }

    // ----- initial feasible schedule -----
    bool feas0;
    ll cmax0;
    vector<vector<int>> order0 = initial_order(feas0, cmax0);
    // order0 is guaranteed feasible, but we keep the check
    if (!feas0) {
        // should never happen
        for (int m = 0; m < M; ++m) {
            for (int j = 0; j < J; ++j) {
                if (j) cout << ' ';
                cout << j;
            }
            if (m + 1 < M) cout << '\n';
        }
        return 0;
    }

    // ----- local search -----
    std::mt19937_64 rng(123456789ULL);   // fixed seed -> deterministic output
    vector<vector<int>> bestOrder = improve(order0, cmax0, rng);

    // ----- output -----
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << bestOrder[m][i];
        }
        if (m + 1 < M) cout << '\n';
    }
    return 0;
}

// Job Shop Scheduling – simple constructive + simulated annealing local search.
// 1) Build a feasible schedule by a greedy earliest‑start rule (random tie‑break).
//    While scheduling we record the order in which each machine processes the jobs.
// 2) Improve the machine orders by repeatedly swapping adjacent jobs
//    (a classic neighbourhood).  The makespan of a given order is computed
//    by longest‑path DP on the disjunctive graph (Kahn topological order).
//    A simulated‑annealing acceptance rule allows occasional uphill moves.
// 3) The best feasible order found within the time limit is printed.
//
// The program is deterministic (fixed random seed) and conforms to the
// required output format.

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int J, M;
    if (!(cin >> J >> M)) return 0;

    const int N = J * M;                     // total operations
    vector<vector<int>> job_machines(J, vector<int>(M));
    vector<vector<long long>> job_proc(J, vector<long long>(M));
    vector<long long> job_total(J, 0);
    vector<long long> machine_total(M, 0);

    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m; long long p;
            cin >> m >> p;
            job_machines[j][k] = m;
            job_proc[j][k] = p;
            job_total[j] += p;
            machine_total[m] += p;
        }
    }

    // position of each machine inside a job
    vector<vector<int>> pos_of_machine(J, vector<int>(M));
    for (int j = 0; j < J; ++j)
        for (int k = 0; k < M; ++k)
            pos_of_machine[j][job_machines[j][k]] = k;

    // operation id mapping and basic data
    vector<vector<int>> op_id(J, vector<int>(M));
    vector<long long> proc(N);
    vector<int> succ_job(N, -1);
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int id = j * M + k;
            int m = job_machines[j][k];
            op_id[j][m] = id;
            proc[id] = job_proc[j][k];
            if (k + 1 < M) succ_job[id] = j * M + (k + 1);
        }
    }

    // ---------- 1) constructive greedy schedule (random tie‑break) ----------
    mt19937 rng(123456);                     // fixed seed for reproducibility
    vector<int> idx(J, 0);                   // next operation index per job
    vector<long long> job_ready(J, 0);
    vector<long long> machine_ready(M, 0);
    vector<vector<int>> order(M, vector<int>());
    for (int m = 0; m < M; ++m) order[m].reserve(J);
    int remaining = J * M;

    while (remaining > 0) {
        long long best_time = LLONG_MAX;
        // first pass: find minimal ready time
        for (int j = 0; j < J; ++j) if (idx[j] < M) {
            int m = job_machines[j][idx[j]];
            long long t = max(job_ready[j], machine_ready[m]);
            if (t < best_time) best_time = t;
        }
        // collect all jobs achieving that time
        vector<int> cand;
        cand.reserve(J);
        for (int j = 0; j < J; ++j) if (idx[j] < M) {
            int m = job_machines[j][idx[j]];
            long long t = max(job_ready[j], machine_ready[m]);
            if (t == best_time) cand.push_back(j);
        }
        uniform_int_distribution<int> dist_cand(0, (int)cand.size() - 1);
        int j = cand[dist_cand(rng)];
        int k = idx[j];
        int m = job_machines[j][k];
        long long start = max(job_ready[j], machine_ready[m]);
        long long finish = start + job_proc[j][k];
        job_ready[j] = finish;
        machine_ready[m] = finish;
        order[m].push_back(j);
        ++idx[j];
        --remaining;
    }

    // ---------- helper data for makespan computation ----------
    // indegree contributed by job arcs only (position > 0)
    vector<int> indeg_job(N, 0);
    for (int j = 0; j < J; ++j)
        for (int k = 1; k < M; ++k)
            indeg_job[j * M + k] = 1;

    // lower bound (max of job and machine total times)
    long long lower_bound = 0;
    for (int j = 0; j < J; ++j) lower_bound = max(lower_bound, job_total[j]);
    for (int m = 0; m < M; ++m) lower_bound = max(lower_bound, machine_total[m]);

    // ---------- makespan evaluator ----------
    auto computeMakespan = [&](const vector<vector<int>>& ord, long long& makespan) -> bool {
        static vector<int> indeg; indeg = indeg_job;                 // copy base indegree
        static vector<int> succ_machine(N, -1);
        static vector<long long> earliest(N, 0);
        fill(succ_machine.begin(), succ_machine.end(), -1);
        // machine arcs
        for (int m = 0; m < M; ++m) {
            const auto& seq = ord[m];
            for (int i = 0; i + 1 < (int)seq.size(); ++i) {
                int u = op_id[seq[i]][m];
                int v = op_id[seq[i + 1]][m];
                succ_machine[u] = v;
                indeg[v]++;                 // add incoming edge
            }
        }
        deque<int> q;
        for (int i = 0; i < N; ++i) {
            earliest[i] = 0;
            if (indeg[i] == 0) q.push_back(i);
        }
        int processed = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop_front();
            ++processed;
            long long finish = earliest[u] + proc[u];
            int v = succ_job[u];
            if (v != -1) {
                if (earliest[v] < finish) earliest[v] = finish;
                if (--indeg[v] == 0) q.push_back(v);
            }
            v = succ_machine[u];
            if (v != -1) {
                if (earliest[v] < finish) earliest[v] = finish;
                if (--indeg[v] == 0) q.push_back(v);
            }
        }
        if (processed != N) return false;   // cycle -> infeasible
        long long maxFinish = 0;
        for (int i = 0; i < N; ++i) {
            long long f = earliest[i] + proc[i];
            if (f > maxFinish) maxFinish = f;
        }
        makespan = maxFinish;
        return true;
    };

    // initial makespan
    long long cur_make;
    computeMakespan(order, cur_make);
    vector<vector<int>> best_order = order;
    long long best_make = cur_make;

    // ---------- 2) simulated annealing local search ----------
    const double TIME_LIMIT = 0.94;               // seconds
    auto start_time = chrono::steady_clock::now();

    double init_temp = double(cur_make > lower_bound ? cur_make - lower_bound : 1);
    uniform_int_distribution<int> distM(0, M - 1);
    uniform_int_distribution<int> distPos(0, J - 2);
    uniform_real_distribution<double> distReal(0.0, 1.0);

    vector<vector<int>> cur_order = order;
    while (true) {
        auto now = chrono::steady_clock::now();
        double elapsed = chrono::duration<double>(now - start_time).count();
        if (elapsed >= TIME_LIMIT) break;
        int m = distM(rng);
        int i = distPos(rng);
        swap(cur_order[m][i], cur_order[m][i + 1]);

        long long new_make;
        bool feasible = computeMakespan(cur_order, new_make);
        if (!feasible) {
            swap(cur_order[m][i], cur_order[m][i + 1]); // revert
            continue;
        }

        long long delta = new_make - cur_make;
        double temperature = init_temp * (1.0 - elapsed / TIME_LIMIT);
        bool accept = false;
        if (delta < 0) accept = true;
        else if (temperature > 0.0) {
            double prob = exp(-static_cast<double>(delta) / temperature);
            if (distReal(rng) < prob) accept = true;
        }
        if (accept) {
            cur_make = new_make;
            if (new_make < best_make) {
                best_make = new_make;
                best_order = cur_order;
            }
        } else {
            swap(cur_order[m][i], cur_order[m][i + 1]); // revert
        }
    }

    // ---------- 3) output ----------
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << best_order[m][i];
        }
        if (m + 1 < M) cout << '\n';
    }
    return 0;
}

/*
 *  Job Shop Scheduling – heuristic with Giffler‑Thompson construction
 *  and simple local search (adjacent swaps).  The program builds several
 *  initial schedules using different priority rules, improves them by
 *  repeatedly swapping adjacent jobs on each machine while the makespan
 *  decreases, and finally performs a short stochastic hill‑climb.
 *  The best schedule (machine job orders) is printed.
 *
 *  The makespan of a schedule is computed by a longest‑path (topological)
 *  DP on the disjunctive graph formed by job arcs and the chosen machine
 *  order arcs.  If the graph contains a cycle the schedule is rejected.
 *
 *  The code follows the outlined algorithm and fits easily into the
 *  1‑second per‑case limit for the given input sizes (J≤50, M≤25).
 */

#include <bits/stdc++.h>
using namespace std;

struct Op {
    int machine;
    int proc;
};

int J, M;
int N;                                     // total number of operations = J * M
vector<vector<Op>> jobOps;                // jobOps[j][k]
vector<vector<int>> posInJob;             // posInJob[j][machine] = k
vector<long long> totalJobProc;           // sum of processing times per job
vector<int> proc_of_op;                   // processing time of each node (j*M+k)

vector<vector<int>> adj;                  // adjacency for DP (reused)
vector<int> indeg;                        // indegree for DP (reused)
vector<long long> distv;                  // earliest start times (reused)

// ------------------------------------------------------------------
// Compute makespan of a given machine order.
// Returns true iff the schedule is feasible (no cycles).
// The makespan is stored in 'makespan'.
bool evaluate(const vector<vector<int>>& order, long long &makespan) {
    // clear adjacency & indegree
    for (int i = 0; i < N; ++i) adj[i].clear();
    fill(indeg.begin(), indeg.end(), 0);
    // job arcs (linear chain inside each job)
    for (int j = 0; j < J; ++j) {
        for (int k = 1; k < M; ++k) {
            int pred = j * M + k - 1;
            int cur  = j * M + k;
            adj[pred].push_back(cur);
            indeg[cur]++;
        }
    }
    // machine arcs from the given order
    for (int m = 0; m < M; ++m) {
        const vector<int> &line = order[m];
        for (int i = 0; i + 1 < (int)line.size(); ++i) {
            int jp = line[i];
            int jn = line[i + 1];
            int pred = jp * M + posInJob[jp][m];
            int cur  = jn * M + posInJob[jn][m];
            adj[pred].push_back(cur);
            indeg[cur]++;
        }
    }
    // topological DP (longest path)
    queue<int> q;
    for (int v = 0; v < N; ++v) {
        distv[v] = 0;
        if (indeg[v] == 0) q.push(v);
    }
    int processed = 0;
    makespan = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        ++processed;
        long long finish = distv[u] + proc_of_op[u];
        if (finish > makespan) makespan = finish;
        for (int v : adj[u]) {
            if (distv[v] < finish) distv[v] = finish;
            if (--indeg[v] == 0) q.push(v);
        }
    }
    return processed == N;                // true -> feasible
}

// ------------------------------------------------------------------
// Build a schedule using a simple list scheduling (Giffler‑Thompson)
// with the given priority rule.
//   0 – earliest finish time (default)
//   1 – shortest processing time
//   2 – longest processing time
//   3 – smallest remaining total work
//   4 – largest remaining total work
void scheduleGt(int rule, vector<vector<int>>& order) {
    order.assign(M, vector<int>());
    vector<int> jobNext(J, 0);
    vector<long long> jobReady(J, 0);
    vector<long long> machReady(M, 0);
    vector<long long> remWork = totalJobProc;   // copy

    int scheduled = 0;
    const int totalOps = J * M;

    while (scheduled < totalOps) {
        int bestJob = -1;
        long long bestKey = LLONG_MAX;
        long long bestFinish = LLONG_MAX;

        for (int j = 0; j < J; ++j) {
            int k = jobNext[j];
            if (k >= M) continue;               // already finished
            const Op &op = jobOps[j][k];
            int m = op.machine;
            int p = op.proc;
            long long start = max(jobReady[j], machReady[m]);
            long long finish = start + p;
            long long key;
            switch (rule) {
                case 0: key = finish; break;                 // earliest finish
                case 1: key = p; break;                       // shortest processing
                case 2: key = -static_cast<long long>(p); break; // longest processing
                case 3: key = remWork[j]; break;             // smallest remaining total
                case 4: key = -remWork[j]; break;            // largest remaining total
                default: key = finish;
            }
            if (key < bestKey ||
                (key == bestKey && finish < bestFinish) ||
                (key == bestKey && finish == bestFinish && j < bestJob)) {
                bestKey = key;
                bestFinish = finish;
                bestJob = j;
            }
        }

        // schedule the chosen operation
        int j = bestJob;
        int k = jobNext[j];
        const Op &op = jobOps[j][k];
        int m = op.machine;
        int p = op.proc;
        long long start = max(jobReady[j], machReady[m]);
        long long finish = start + p;

        order[m].push_back(j);
        jobReady[j] = finish;
        machReady[m] = finish;
        remWork[j] -= p;
        jobNext[j] = k + 1;
        ++scheduled;
    }
}

// ------------------------------------------------------------------
// Simple deterministic local search: try all adjacent swaps on all machines
// and keep any swap that strictly reduces the makespan.
// Stops when a full pass yields no improvement or time runs out.
void localSearch(vector<vector<int>>& order, long long &bestMake,
                 const chrono::steady_clock::time_point& deadline) {
    while (true) {
        bool improved = false;
        for (int m = 0; m < M; ++m) {
            for (int i = 0; i + 1 < J; ++i) {
                if (chrono::steady_clock::now() > deadline) return;
                swap(order[m][i], order[m][i + 1]);
                long long newMake;
                bool ok = evaluate(order, newMake);
                if (ok && newMake < bestMake) {
                    bestMake = newMake;
                    improved = true;               // keep the swap
                } else {
                    swap(order[m][i], order[m][i + 1]); // revert
                }
            }
        }
        if (!improved) break;
    }
}

// ------------------------------------------------------------------
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    if (!(cin >> J >> M)) return 0;
    N = J * M;

    jobOps.assign(J, vector<Op>(M));
    posInJob.assign(J, vector<int>(M, -1));
    totalJobProc.assign(J, 0);
    proc_of_op.resize(N);

    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m, p;
            cin >> m >> p;
            jobOps[j][k] = {m, p};
            posInJob[j][m] = k;
            totalJobProc[j] += p;
            proc_of_op[j * M + k] = p;
        }
    }

    adj.assign(N, vector<int>());
    indeg.resize(N);
    distv.resize(N);

    // overall time budget (slightly less than the per‑case limit)
    const double TIME_LIMIT = 1.85; // seconds
    auto startTime = chrono::steady_clock::now();
    auto deadline = startTime + chrono::duration<double>(TIME_LIMIT);

    vector<vector<int>> bestOrder;
    long long bestMake = LLONG_MAX;

    // try a few deterministic priority rules
    const vector<int> rules = {0, 1, 2, 3, 4};
    for (int r : rules) {
        if (chrono::steady_clock::now() > deadline) break;
        vector<vector<int>> curOrder;
        scheduleGt(r, curOrder);
        long long curMake;
        if (!evaluate(curOrder, curMake)) continue; // should not happen
        localSearch(curOrder, curMake, deadline);
        if (curMake < bestMake) {
            bestMake = curMake;
            bestOrder = curOrder;
        }
    }

    // short stochastic hill climbing (adjacent swaps)
    if (!bestOrder.empty()) {
        std::mt19937 rng(123456789);
        vector<vector<int>> curOrder = bestOrder;
        long long curMake = bestMake;
        uniform_int_distribution<int> distM(0, M - 1);
        uniform_int_distribution<int> distPos(0, J - 2);
        while (chrono::steady_clock::now() < deadline) {
            int m = distM(rng);
            int i = distPos(rng);
            swap(curOrder[m][i], curOrder[m][i + 1]);
            long long newMake;
            bool ok = evaluate(curOrder, newMake);
            if (ok && newMake <= curMake) {
                curMake = newMake;
                if (newMake < bestMake) {
                    bestMake = newMake;
                    bestOrder = curOrder;
                }
                // keep the swap (even if equal, to wander a bit)
            } else {
                swap(curOrder[m][i], curOrder[m][i + 1]); // revert
            }
        }
    }

    // Output: exactly M lines, each a permutation of 0..J-1
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << bestOrder[m][i];
        }
        if (m + 1 < M) cout << '\n';
    }
    return 0;
}

/*
 * Job‑Shop Scheduling – open optimization
 * ------------------------------------------------------------
 * 1. Construct many feasible schedules by a simple list‑scheduling
 *    algorithm.  In each step a ready operation (next operation of a
 *    job) is chosen according to a randomly selected priority rule
 *    (earliest start, shortest/longest processing time, random or a
 *    weighted combination of both).  The chosen operation is appended
 *    to the order of its machine; this guarantees a feasible orientation
 *    of all disjunctive arcs.
 *
 * 2. The makespan of a given set of machine orders is obtained by
 *    longest‑path computation on the corresponding disjunctive graph.
 *    The graph consists of J·M nodes, each node has at most two outgoing
 *    edges (job‑successor and machine‑successor).  A Kahn topological
 *    traversal yields the earliest start times and the makespan.
 *
 * 3. After a schedule is built, a cheap local search swaps adjacent jobs
 *    on a random machine.  The swap is kept only if it reduces the
 *    makespan (and does not create a cycle).  This hill‑climbing step
 *    is repeated while time permits.
 *
 * 4. The best (smallest makespan) schedule found within the time limit
 *    is printed as M permutations, one per machine.
 *
 * The program runs under the time limit (≈2 s) and uses only standard
 * C++17 facilities.
 */

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF_LL = (1LL << 60);

int J, M;                                   // number of jobs / machines
vector<vector<int>> route;                  // route[j][k] = machine of k‑th op of job j
vector<vector<ll>>  proc;                   // proc [j][k] = processing time
vector<vector<int>> jobPos;                 // jobPos[j][m] = index k of machine m in job j
vector<ll> procFlat;                        // flattened processing times (size J*M)

// ------------------------------------------------------------
// compute makespan for a given set of machine orders
// returns INF_LL if the orientation creates a cycle (infeasible)
ll computeMakespan(const vector<vector<int>>& order) {
    const int N = J * M;
    static vector<int> indeg;
    static vector<int> succMachine;
    indeg.assign(N, 0);
    succMachine.assign(N, -1);

    // job arcs
    for (int j = 0; j < J; ++j)
        for (int k = 0; k + 1 < M; ++k)
            indeg[j * M + (k + 1)]++;

    // machine arcs
    for (int m = 0; m < M; ++m) {
        const vector<int>& perm = order[m];
        for (int i = 0; i + 1 < J; ++i) {
            int uJob = perm[i];
            int vJob = perm[i + 1];
            int uIdx = jobPos[uJob][m];
            int vIdx = jobPos[vJob][m];
            int idU  = uJob * M + uIdx;
            int idV  = vJob * M + vIdx;
            indeg[idV]++;
            succMachine[idU] = idV;
        }
    }

    vector<ll> start(N, 0);
    deque<int> q;
    for (int i = 0; i < N; ++i)
        if (indeg[i] == 0) q.push_back(i);

    int processed = 0;
    ll makespan = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop_front();
        ll finishU = start[u] + procFlat[u];
        makespan = max(makespan, finishU);
        ++processed;

        // job successor (same job, next operation)
        int k = u % M;
        if (k + 1 < M) {
            int v = u + 1;               // next operation of the same job
            if (start[v] < finishU) start[v] = finishU;
            if (--indeg[v] == 0) q.push_back(v);
        }

        // machine successor
        int v = succMachine[u];
        if (v != -1) {
            if (start[v] < finishU) start[v] = finishU;
            if (--indeg[v] == 0) q.push_back(v);
        }
    }
    if (processed < N) return INF_LL;   // cycle -> infeasible
    return makespan;
}

// ------------------------------------------------------------
// construct a schedule using a given priority rule
// rule = 0: earliest start
// rule = 1: shortest processing time
// rule = 2: longest processing time
// rule = 3: completely random
// rule = 4: weighted combination of start and processing time
void constructSchedule(vector<vector<int>>& order, ll& makespan,
                       int rule, double wStart, double wProc,
                       mt19937& rng) {
    order.assign(M, vector<int>());
    for (int m = 0; m < M; ++m) order[m].reserve(J);

    vector<int> nxt(J, 0);
    vector<ll> jobReady(J, 0);
    vector<ll> machReady(M, 0);
    int remaining = J * M;

    uniform_real_distribution<double> uni01(0.0, 1.0);
    uniform_int_distribution<int> anyJob; // will be re‑initialized later

    while (remaining) {
        double bestScore = numeric_limits<double>::infinity();
        vector<int> cand;
        cand.reserve(J);
        for (int j = 0; j < J; ++j) {
            int idx = nxt[j];
            if (idx == M) continue;            // job finished
            int m = route[j][idx];
            ll es = max(jobReady[j], machReady[m]);
            ll p  = proc[j][idx];
            double score;
            switch (rule) {
                case 0: score = static_cast<double>(es); break;                     // earliest start
                case 1: score = static_cast<double>(p);  break;                     // shortest proc.
                case 2: score = -static_cast<double>(p); break;                     // longest (negative)
                case 3: score = uni01(rng);           break;                     // random
                case 4: score = wStart * es + wProc * p; break;                     // weighted
                default: score = static_cast<double>(es);
            }
            if (score < bestScore - 1e-12) {
                bestScore = score;
                cand.clear();
                cand.push_back(j);
            } else if (fabs(score - bestScore) <= 1e-12) {
                cand.push_back(j);
            }
        }
        // pick randomly among the best candidates
        uniform_int_distribution<int> pick(0, (int)cand.size() - 1);
        int j = cand[pick(rng)];
        int idx = nxt[j];
        int m = route[j][idx];
        ll start = max(jobReady[j], machReady[m]);
        ll fin   = start + proc[j][idx];
        jobReady[j] = fin;
        machReady[m] = fin;
        order[m].push_back(j);
        nxt[j] = idx + 1;
        --remaining;
    }
    makespan = *max_element(jobReady.begin(), jobReady.end());
}

// ------------------------------------------------------------

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> J >> M)) return 0;
    route.assign(J, vector<int>(M));
    proc.assign(J, vector<ll>(M));
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m; ll p;
            cin >> m >> p;
            route[j][k] = m;
            proc[j][k] = p;
        }
    }

    // jobPos[j][machine] = position of that machine in job j
    jobPos.assign(J, vector<int>(M));
    for (int j = 0; j < J; ++j)
        for (int k = 0; k < M; ++k)
            jobPos[j][route[j][k]] = k;

    // flattened processing times
    procFlat.resize(J * M);
    for (int j = 0; j < J; ++j)
        for (int k = 0; k < M; ++k)
            procFlat[j * M + k] = proc[j][k];

    // random generator (fixed seed for reproducibility)
    mt19937 rng(123456789);
    uniform_real_distribution<double> uni01(0.0, 1.0);
    uniform_int_distribution<int> ruleDist(0, 4);

    vector<vector<int>> bestOrder;
    ll bestC = INF_LL;

    using clock = chrono::steady_clock;
    auto startTime = clock::now();
    const double TIME_LIMIT = 1.90;               // seconds, leave margin

    // Main meta‑heuristic loop
    while (chrono::duration<double>(clock::now() - startTime).count() < TIME_LIMIT) {
        int rule = ruleDist(rng);
        double wStart = uni01(rng);
        double wProc  = uni01(rng);

        vector<vector<int>> curOrder;
        ll curC;
        constructSchedule(curOrder, curC, rule, wStart, wProc, rng);

        // ----- local hill climbing (adjacent swaps) -----
        // Number of attempts is limited both by a fixed budget and by remaining time.
        const int MAX_LOCAL_ATTEMPTS = 3000;
        for (int it = 0; it < MAX_LOCAL_ATTEMPTS; ++it) {
            if (chrono::duration<double>(clock::now() - startTime).count() >= TIME_LIMIT) break;
            if (J <= 1) break;
            int m = uniform_int_distribution<int>(0, M - 1)(rng);
            int pos = uniform_int_distribution<int>(0, J - 2)(rng);
            swap(curOrder[m][pos], curOrder[m][pos + 1]);
            ll newC = computeMakespan(curOrder);
            if (newC < curC) {
                curC = newC;                 // keep improvement
            } else {
                swap(curOrder[m][pos], curOrder[m][pos + 1]); // revert
            }
        }

        if (curC < bestC) {
            bestC = curC;
            bestOrder = std::move(curOrder);
        }
    }

    // Fallback (should never happen)
    if (bestOrder.empty()) {
        bestOrder.assign(M, vector<int>(J));
        for (int m = 0; m < M; ++m)
            for (int j = 0; j < J; ++j)
                bestOrder[m][j] = j;
    }

    // Output
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << bestOrder[m][i];
        }
        if (m + 1 < M) cout << '\n';
    }
    return 0;
}

/*
 * Job‑Shop Open‑Optimization Solver
 * ---------------------------------
 * The program builds a feasible schedule by a greedy list‑scheduling (a
 * Giffler‑Thompson style heuristic).  At every step it schedules the
 * operation that can start the earliest; ties are broken by the larger
 * amount of remaining work (sum of processing times of the not yet
 * processed operations of that job).  Random tie‑breaking is used and the
 * heuristic is run repeatedly within the time limit; the best schedule
 * (smallest makespan) is kept and its machine orders are output.
 *
 * The schedule itself is constructed step by step, therefore the
 * resulting machine orders are guaranteed to be feasible (they come from
 * an actual schedule, so no cycles can appear).
 *
 * Complexity per iteration: O(J·M) operations (≤ 1250) – easily fits the
 * time limit, allowing many repetitions for better solutions.
 */

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int J, M;
    if (!(cin >> J >> M)) return 0;

    vector<vector<int>> jobMach(J, vector<int>(M));
    vector<vector<long long>> jobProc(J, vector<long long>(M));
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m; long long p;
            cin >> m >> p;
            jobMach[j][k] = m;
            jobProc[j][k] = p;
        }
    }

    // suffix[j][i] = sum_{t=i}^{M-1} proc of job j (remaining work incl. current)
    vector<vector<long long>> suffix(J, vector<long long>(M + 1, 0));
    for (int j = 0; j < J; ++j) {
        suffix[j][M] = 0;
        for (int i = M - 1; i >= 0; --i)
            suffix[j][i] = suffix[j][i + 1] + jobProc[j][i];
    }

    // Greedy schedule generator (returns makespan and machine orders)
    auto runSchedule = [&](mt19937& rng) -> pair<long long, vector<vector<int>>> {
        vector<int> opIdx(J, 0);                 // next operation index per job
        vector<long long> ready(J, 0);           // completion time of last scheduled op of each job
        vector<long long> machAvail(M, 0);       // when each machine becomes free
        vector<vector<int>> order(M);
        for (int m = 0; m < M; ++m) order[m].reserve(J);

        const int totalOps = J * M;
        int scheduled = 0;
        while (scheduled < totalOps) {
            long long bestStart = LLONG_MAX;
            // 1) find the earliest possible start time among all ready operations
            for (int j = 0; j < J; ++j) {
                int idx = opIdx[j];
                if (idx == M) continue;
                int m = jobMach[j][idx];
                long long start = max(ready[j], machAvail[m]);
                if (start < bestStart) bestStart = start;
            }
            // 2) among those with earliest start, keep the ones with maximal remaining work
            long long maxRem = -1;
            for (int j = 0; j < J; ++j) {
                int idx = opIdx[j];
                if (idx == M) continue;
                int m = jobMach[j][idx];
                long long start = max(ready[j], machAvail[m]);
                if (start == bestStart) {
                    long long rem = suffix[j][idx];
                    if (rem > maxRem) maxRem = rem;
                }
            }
            // 3) collect candidates and pick one uniformly at random
            vector<int> cand;
            cand.reserve(J);
            for (int j = 0; j < J; ++j) {
                int idx = opIdx[j];
                if (idx == M) continue;
                int m = jobMach[j][idx];
                long long start = max(ready[j], machAvail[m]);
                if (start == bestStart && suffix[j][idx] == maxRem)
                    cand.push_back(j);
            }
            uniform_int_distribution<int> dist(0, (int)cand.size() - 1);
            int chosen = cand[dist(rng)];

            // schedule the chosen operation
            int idx = opIdx[chosen];
            int m = jobMach[chosen][idx];
            long long p = jobProc[chosen][idx];
            long long start = bestStart;
            long long finish = start + p;

            ready[chosen] = finish;
            machAvail[m] = finish;
            order[m].push_back(chosen);
            ++opIdx[chosen];
            ++scheduled;
        }

        long long makespan = 0;
        for (long long t : ready) if (t > makespan) makespan = t;
        return {makespan, order};
    };

    // deterministic first run (still uses the same random choices)
    mt19937 rng(123456789);
    long long bestMakespan = LLONG_MAX;
    vector<vector<int>> bestOrder;

    {
        auto res = runSchedule(rng);
        bestMakespan = res.first;
        bestOrder = move(res.second);
    }

    // repeat while we have time left
    auto tStart = chrono::steady_clock::now();
    const double TIME_LIMIT = 0.94; // seconds
    while (true) {
        auto now = chrono::steady_clock::now();
        double elapsed = chrono::duration<double>(now - tStart).count();
        if (elapsed > TIME_LIMIT) break;
        auto res = runSchedule(rng);
        if (res.first < bestMakespan) {
            bestMakespan = res.first;
            bestOrder = move(res.second);
        }
    }

    // output machine orders
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << bestOrder[m][i];
        }
        cout << '\n';
    }
    return 0;
}

/*
  Job Shop Scheduling – heuristic solution
  ---------------------------------------
  * Randomised list scheduling:
        - Repeatedly schedule the next operation of any job.
        - For each ready operation compute:
                start = max(jobReady, machineReady)
                priority = start + α * processingTime  (α random in [0,2])
        - Choose the operation with minimal priority (ties broken randomly).
        - Record the chosen job on the machine → this builds the machine permutation.
  * Keep the best schedule (smallest makespan) among many runs within the time limit.
  * Local improvement (hill‑climbing):
        - Repeatedly try to swap adjacent jobs on each machine.
        - After a swap recompute the makespan by longest‑path DP on the
          disjunctive graph (job arcs + machine arcs).
        - Keep the swap only if the graph stays acyclic and the makespan improves.
  * Output the final machine permutations.
*/

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Op {
    int mach;
    int t;
};

int J, M;
vector<vector<Op>> jobOps;          // jobOps[j][k] = k-th operation of job j
vector<vector<int>> jobOpIdx;       // jobOpIdx[j][machine] = position k of that machine in job j
vector<int> proc;                   // processing time of each node (job*m + k)

vector<vector<int>> adj;            // adjacency list for longest‑path DP
vector<int> indeg;
vector<ll> earliest;

/* Compute makespan for a given set of machine orders.
   Returns true iff the graph is acyclic. */
bool computeMakespan(const vector<vector<int>>& seq, ll& makespan) {
    int N = J * M;
    for (int i = 0; i < N; ++i) {
        adj[i].clear();
        indeg[i] = 0;
        earliest[i] = 0;
    }

    // job precedence arcs
    for (int j = 0; j < J; ++j) {
        int base = j * M;
        for (int k = 0; k < M - 1; ++k) {
            int u = base + k;
            int v = base + k + 1;
            adj[u].push_back(v);
            ++indeg[v];
        }
    }

    // machine arcs (according to the supplied order)
    for (int m = 0; m < M; ++m) {
        const auto& order = seq[m];
        for (int i = 0; i < J - 1; ++i) {
            int ja = order[i];
            int jb = order[i + 1];
            int oa = jobOpIdx[ja][m];
            int ob = jobOpIdx[jb][m];
            int u = ja * M + oa;
            int v = jb * M + ob;
            adj[u].push_back(v);
            ++indeg[v];
        }
    }

    // topological DP
    deque<int> q;
    for (int i = 0; i < N; ++i) if (indeg[i] == 0) q.push_back(i);
    int processed = 0;
    makespan = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop_front();
        ll finish = earliest[u] + proc[u];
        if (finish > makespan) makespan = finish;
        for (int v : adj[u]) {
            if (earliest[v] < finish) earliest[v] = finish;
            if (--indeg[v] == 0) q.push_back(v);
        }
        ++processed;
    }
    return processed == N;   // true ⇔ graph is a DAG
}

/* One run of the randomised list‑scheduling heuristic.
   Returns makespan and fills 'seq' with the machine orders. */
void scheduleRun(double alpha, vector<vector<int>>& seq, ll& makespan, mt19937_64& rng) {
    vector<int> nextIdx(J, 0);
    vector<ll> jobReady(J, 0);
    vector<ll> machReady(M, 0);
    seq.assign(M, vector<int>());

    uniform_real_distribution<double> epsDist(0.0, 1e-6);
    int totalOps = J * M;
    int done = 0;
    while (done < totalOps) {
        double bestScore = 1e300;
        int bestJob = -1;
        ll bestStart = 0;
        int bestMach = -1;
        int bestProc = 0;

        for (int j = 0; j < J; ++j) {
            int idx = nextIdx[j];
            if (idx >= M) continue;                     // job finished
            const Op& op = jobOps[j][idx];
            ll start = max(jobReady[j], machReady[op.mach]);
            double score = (double)start + alpha * (double)op.t + epsDist(rng);
            if (score < bestScore) {
                bestScore = score;
                bestJob = j;
                bestStart = start;
                bestMach = op.mach;
                bestProc = op.t;
            }
        }

        // schedule the chosen operation
        ll finish = bestStart + bestProc;
        jobReady[bestJob] = finish;
        machReady[bestMach] = finish;
        seq[bestMach].push_back(bestJob);
        ++nextIdx[bestJob];
        ++done;
    }

    makespan = *max_element(jobReady.begin(), jobReady.end());
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> J >> M)) return 0;
    jobOps.assign(J, vector<Op>(M));
    jobOpIdx.assign(J, vector<int>(M, -1));

    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m, p;
            cin >> m >> p;
            jobOps[j][k] = {m, p};
            jobOpIdx[j][m] = k;
        }
    }

    // processing times per node
    proc.resize(J * M);
    for (int j = 0; j < J; ++j)
        for (int k = 0; k < M; ++k)
            proc[j * M + k] = jobOps[j][k].t;

    // adjacency structures for DP (reuse to avoid many allocations)
    adj.assign(J * M, vector<int>());
    indeg.assign(J * M, 0);
    earliest.assign(J * M, 0);
    for (auto& v : adj) v.reserve(2);   // each node has at most two outgoing arcs

    mt19937_64 rng(123456789ULL);               // fixed seed → deterministic overall
    uniform_real_distribution<double> alphaDist(0.0, 2.0);

    vector<vector<int>> bestSeq;
    ll bestMakespan = LLONG_MAX;

    // --- initial deterministic run ---
    {
        vector<vector<int>> seq;
        ll makespan;
        scheduleRun(1.0, seq, makespan, rng);
        bestSeq.swap(seq);
        bestMakespan = makespan;
    }

    // --- many random runs within time limit ---
    auto startTime = chrono::steady_clock::now();
    const double TIME_LIMIT = 0.95; // seconds total
    while (chrono::duration<double>(chrono::steady_clock::now() - startTime).count() < TIME_LIMIT) {
        double alpha = alphaDist(rng);
        vector<vector<int>> seq;
        ll makespan;
        scheduleRun(alpha, seq, makespan, rng);
        if (makespan < bestMakespan) {
            bestMakespan = makespan;
            bestSeq.swap(seq);
        }
    }

    // --- hill climbing: adjacent swaps on each machine ---
    while (chrono::duration<double>(chrono::steady_clock::now() - startTime).count() < TIME_LIMIT) {
        bool anyImproved = false;
        for (int m = 0; m < M; ++m) {
            auto& order = bestSeq[m];
            for (int i = 0; i < J - 1; ++i) {
                swap(order[i], order[i + 1]);                 // try swap
                ll newMakespan;
                if (!computeMakespan(bestSeq, newMakespan) || newMakespan >= bestMakespan) {
                    swap(order[i], order[i + 1]);             // revert
                } else {
                    bestMakespan = newMakespan;
                    anyImproved = true;                       // keep the improvement
                }
            }
        }
        if (!anyImproved) break;
    }

    // --- output ---
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << bestSeq[m][i];
        }
        if (m + 1 < M) cout << '\n';
    }
    return 0;
}

/*
   Job Shop Scheduling – open optimisation
   -------------------------------------------------
   1) build a feasible schedule by a simple list‑scheduler,
      remembering the order in which each machine processes the jobs
   2) hill‑climbing: repeatedly try all adjacent swaps on all machines,
      keep a swap only if it strictly reduces the makespan
   3) makespan of a permutation set is obtained by a topological DP
      (Kahn's algorithm) on the disjunctive graph.
   The whole algorithm finishes far below the 1 s limit and always
   prints a feasible schedule.
*/

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int J, M, N;                     // jobs, machines, operations
vector<vector<int>> opMach;     // opMach[j][k] = machine of k‑th op of job j
vector<vector<ll>>  opProc;     // processing time
vector<vector<int>> posInJob;   // posInJob[j][m] = index k of machine m in job j

// static data for the DP
vector<ll> proc;                // processing time of node id = j*M + k
vector<int> jobSucc;            // next operation of the same job, -1 if none
vector<int> baseIndeg;          // 1 if operation has job predecessor, else 0

// ---------- makespan evaluation ----------
ll makespan(const vector<vector<int>>& order) {
    static int indeg[1250];
    static ll  earliest[1250];
    static int machineSucc[1250];
    int n = N;
    // copy static indegree (job edges only)
    for (int i = 0; i < n; ++i) indeg[i] = baseIndeg[i];
    for (int i = 0; i < n; ++i) earliest[i] = 0;
    for (int i = 0; i < n; ++i) machineSucc[i] = -1;

    // add machine edges
    for (int m = 0; m < M; ++m) {
        const vector<int> &o = order[m];
        for (int i = 0; i + 1 < J; ++i) {
            int jobU = o[i];
            int jobV = o[i+1];
            int nodeU = jobU * M + posInJob[jobU][m];
            int nodeV = jobV * M + posInJob[jobV][m];
            machineSucc[nodeU] = nodeV;
            ++indeg[nodeV];
        }
    }

    // Kahn's algorithm
    static int q[1250];
    int qh = 0, qt = 0;
    for (int i = 0; i < n; ++i)
        if (indeg[i] == 0) q[qt++] = i;

    int processed = 0;
    ll makespan = 0;
    while (qh < qt) {
        int u = q[qh++];
        ++processed;
        ll finish = earliest[u] + proc[u];
        if (finish > makespan) makespan = finish;

        int v = jobSucc[u];
        if (v != -1) {
            if (earliest[v] < finish) earliest[v] = finish;
            if (--indeg[v] == 0) q[qt++] = v;
        }
        v = machineSucc[u];
        if (v != -1) {
            if (earliest[v] < finish) earliest[v] = finish;
            if (--indeg[v] == 0) q[qt++] = v;
        }
    }
    if (processed != n) return -1;          // cycle -> infeasible
    return makespan;
}

// ---------- list scheduler, builds initial permutations ----------
vector<vector<int>> initial_schedule() {
    vector<ll> ready(J, 0);             // when job j becomes ready
    vector<int> nextIdx(J, 0);          // next operation index of job j
    vector<ll> nextFree(M, 0);          // when machine m becomes idle
    vector<vector<int>> order(M);       // result
    int remaining = J * M;

    while (remaining--) {
        ll bestStart = (ll)9e18;
        int bestJob = -1, bestMachine = -1;
        ll bestProc = (ll)9e18;

        for (int j = 0; j < J; ++j) {
            if (nextIdx[j] == M) continue;
            int k = nextIdx[j];
            int m = opMach[j][k];
            ll p = opProc[j][k];
            ll start = max(ready[j], nextFree[m]);
            if (start < bestStart || (start == bestStart && p < bestProc)) {
                bestStart = start;
                bestJob = j;
                bestMachine = m;
                bestProc = p;
            }
        }

        // schedule the chosen operation
        order[bestMachine].push_back(bestJob);
        ll finish = bestStart + bestProc;
        ready[bestJob] = finish;
        nextFree[bestMachine] = finish;
        ++nextIdx[bestJob];
    }
    return order;
}

// ---------------------------------------------------------------

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    if (!(cin >> J >> M)) return 0;
    opMach.assign(J, vector<int>(M));
    opProc.assign(J, vector<ll>(M));
    posInJob.assign(J, vector<int>(M, -1));

    N = J * M;
    proc.assign(N, 0);
    jobSucc.assign(N, -1);
    baseIndeg.assign(N, 0);

    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int m; ll p;
            cin >> m >> p;
            opMach[j][k] = m;
            opProc[j][k] = p;
            posInJob[j][m] = k;
            int id = j * M + k;
            proc[id] = p;
        }
    }

    // static job edges
    for (int j = 0; j < J; ++j) {
        for (int k = 0; k < M; ++k) {
            int id = j * M + k;
            if (k > 0) baseIndeg[id] = 1;
            if (k + 1 < M) jobSucc[id] = j * M + (k + 1);
            else jobSucc[id] = -1;
        }
    }

    // ---------- initial solution ----------
    vector<vector<int>> order = initial_schedule();
    ll bestC = makespan(order);            // must be feasible

    // ---------- local improvement (adjacent swaps) ----------
    const double TIME_LIMIT = 0.90;        // seconds
    auto startTime = chrono::high_resolution_clock::now();

    while (true) {
        auto now = chrono::high_resolution_clock::now();
        double elapsed = chrono::duration<double>(now - startTime).count();
        if (elapsed > TIME_LIMIT) break;

        bool improved = false;
        for (int m = 0; m < M && !improved; ++m) {
            for (int i = 0; i + 1 < J; ++i) {
                swap(order[m][i], order[m][i+1]);
                ll cand = makespan(order);
                if (cand != -1 && cand < bestC) {
                    bestC = cand;
                    improved = true;
                    break;      // keep this swap, restart scanning
                } else {
                    swap(order[m][i], order[m][i+1]); // revert
                }
            }
        }
        if (!improved) break;   // local optimum
    }

    // ---------- output ----------
    for (int m = 0; m < M; ++m) {
        for (int i = 0; i < J; ++i) {
            if (i) cout << ' ';
            cout << order[m][i];
        }
        cout << '\n';
    }
    return 0;
}
